import { type Anatomy, type AnatomyPart, createAnatomy } from "../../machine/anatomy";

/**
 * No `root`, the same divergence as `dialog`, `popover` and `tooltip`: the trigger
 * stays where the author wrote it and the surface is portalled, so the two are
 * siblings with nothing above them.
 *
 * **No `arrow` either, and that one is the menu's own economy.** Neither a desktop
 * menu nor a touch one has a tang — the ergot is the popover's geometry, not this
 * one's — so there is no silhouette to draw, no node to measure and no
 * `--sui-arrow-x/y` to publish.
 *
 * **`triggerItem` is a part of its own, which is a deliberate divergence from
 * Zag and Ark**, who fuse `item` and `trigger` onto a single node. Here that
 * fusion would emit `data-part="menu:item menu:trigger"` — that is, a space — and
 * `architecture.md` reads a space in `data-part` as "this element is a
 * composition": every rule behind `:not([data-part*=" "])` would silently drop off
 * the item that opens a submenu. One token settles it, and the sheet shares the
 * shape with `:is([data-part~="menu:item"], [data-part~="menu:trigger-item"])`.
 */
export type MenuPart =
  | "trigger"
  | "contextTrigger"
  | "indicator"
  | "backdrop"
  | "positioner"
  | "content"
  | "itemGroup"
  | "itemGroupLabel"
  | "item"
  | "triggerItem"
  | "itemSymbol"
  | "itemText"
  | "itemDescription"
  | "itemIndicator"
  | "itemShortcut"
  | "separator"
  | "cancelTrigger";

export const anatomy: Anatomy<MenuPart> = createAnatomy("menu").parts(
  "trigger",
  "contextTrigger",
  "indicator",
  "backdrop",
  "positioner",
  "content",
  "itemGroup",
  "itemGroupLabel",
  "item",
  "triggerItem",
  "itemSymbol",
  "itemText",
  "itemDescription",
  "itemIndicator",
  "itemShortcut",
  "separator",
  "cancelTrigger",
);

export const parts: Record<MenuPart, AnatomyPart> = anatomy.build();

export interface MenuCssVars {
  // --- written ---
  /** Where the surface grows from, so a scale-in starts at the anchor. */
  "--sui-transform-origin": "<position>";
  /** Width of the anchor the surface is placed against. */
  "--sui-anchor-width": "<length>";
  /** Height of the anchor the surface is placed against. */
  "--sui-anchor-height": "<length>";
  /** Room left for the surface's width inside the boundary. */
  "--sui-available-width": "<length>";
  /** Room left for the surface's height inside the boundary. */
  "--sui-available-height": "<length>";
  /** Width of the page scrollbar the scroll lock hides, published on the root. */
  "--sui-scrollbar-width": "<length>";
}

import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import { isComposingEvent, isPrimaryPointer } from "../../dom/event";
import { resolveDir } from "../../dom/text-dir";
import { getRovingKeyAction } from "../../focus/roving-focus";
import { isTypeaheadKey } from "../../interaction/typeahead";
import type { HTMLProps, NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import type { Align, Side } from "../../positioner/compute-position";
import { parts } from "./menu.anatomy";
import {
  CANCEL_VALUE,
  getBackdropId,
  getCancelTriggerId,
  getContentEl,
  getContentId,
  getContextTriggerId,
  getIndicatorId,
  getItemDescriptionId,
  getItemGroupId,
  getItemGroupLabelId,
  getItemId,
  getPositionerId,
  getTriggerId,
} from "./menu.dom";
import { getSubmenuKeyAction, getTriggerOpenAction, toRovingKey } from "./menu.keys";
import type {
  MenuApi,
  MenuItemDescriptionProps,
  MenuItemGroupLabelProps,
  MenuItemGroupProps,
  MenuItemIndicatorProps,
  MenuItemProps,
  MenuOptionItemProps,
  MenuSchema,
} from "./menu.types";

/**
 * How deep this menu sits, for `data-level` — the sheet stacks its drill-in by it.
 * Bounded rather than cycle-checked with a `Set`: a menu tree deeper than this is
 * a bug in the wiring, and the attribute is a styling hook, not a proof.
 */
function getLevel(service: Service<MenuSchema>): number {
  let level = 0;
  let parent = service.refs.get("parent");
  while (parent !== null && level < 16) {
    level++;
    parent = parent.refs.get("parent");
  }
  return level;
}

export function connect<T extends PropTypes>(
  service: Service<MenuSchema>,
  normalize: NormalizeProps<T>,
): MenuApi<T> {
  const { context, computed, prop, send, scope } = service;

  const open = context.get("open");
  const disabled = prop("disabled");
  const presentation = computed("presentation");
  const isSubmenu = computed("isSubmenu");
  const dir = prop("dir");
  const state = open ? "open" : "closed";
  const placement = context.get("currentPlacement");
  // Split here rather than imported: `compute-position` keeps its parser private,
  // and re-exporting one to save this line would widen the positioner's surface.
  const [side, align = "center"] = placement.split("-") as [Side, Align | undefined];

  const triggerId = getTriggerId(scope);
  const contentId = getContentId(scope);
  const highlightedValue = context.get("highlightedValue");
  const flashingValue = context.get("flashingValue");
  const hasSelection = context.get("hasSelectionGutter");
  const hasSymbols = context.get("hasSymbolGutter");
  const hasTrigger = context.get("hasTrigger");
  // Read once, when the highlight landed, and held: the modality of *now* flips to
  // pointer after 300 ms of mouse movement whether or not the focus moved, and a
  // ring that blinks out under the user's hands was the result.
  const focusSource = context.get("focusSource");
  const level = getLevel(service);

  /**
   * Every key the surface answers, on `content` alone. Items carry pointer
   * handlers and nothing else: a keydown bubbles out of the focused item to here,
   * so one table serves the whole menu instead of one per item.
   */
  function onContentKeyDown(event: KeyboardEvent): void {
    if (isComposingEvent(event)) return;
    if (event.ctrlKey || event.metaKey || event.altKey) return;

    const { key } = event;

    // APG Menu Button: Tab leaves the menu entirely. Deliberately not prevented
    // here — either the native Tab carries the focus on from the trigger the
    // restore just handed it back to, or `proxyTabFocus` has already placed it
    // after the trigger itself.
    //
    // **Answered ahead of the `defaultPrevented` gate, and it is the only key that
    // is.** That proxy listens on the document in capture and prevents the default
    // whenever the focus sits on the surface's last tabbable — which, under a
    // roving tabindex, is the highlighted item and therefore *always*. Read after
    // the gate, this branch never ran: Tab moved the focus and left the whole tree
    // open behind it.
    if (key === "Tab") {
      send({ type: "TREE.CLOSE" });
      return;
    }

    if (event.defaultPrevented) return;

    // Escape belongs to the dismissable layer, which listens on the document in
    // capture and only answers for the top-most layer. Handling it here as well
    // would close two levels on one press.
    if (key === "Escape") return;

    if (key === "Enter") {
      if (event.repeat) return;
      event.preventDefault();
      send({ type: "ITEM.ACTIVATE" });
      return;
    }
    // Claimed here so the typeahead cannot see it, and answered on keyup — the APG
    // split `research/input.md` §1 makes a rule across the library.
    if (key === " ") {
      event.preventDefault();
      return;
    }

    // Resolved here and not at the `dir` hoist in `connect`: with no `dir` prop
    // the answer is read off the surface, and a DOM read at the top of `connect`
    // would run on the server. Read once — both lookups below want the same one.
    const keyDir = resolveDir(dir, getContentEl(scope));

    const submenu = getSubmenuKeyAction(key, keyDir);
    if (submenu !== null) {
      event.preventDefault();
      // `CHILD.CLOSE` reads as "close the child, or close me if I am one", so the
      // same event is `back` at every depth and a no-op at the root.
      send(submenu === "open" ? { type: "CHILD.OPEN", focus: true } : { type: "CHILD.CLOSE" });
      return;
    }

    const action = getRovingKeyAction(toRovingKey(key), {
      orientation: "vertical",
      dir: keyDir,
    });
    if (action !== null) {
      event.preventDefault();
      send({ type: "HIGHLIGHT.MOVE", action });
      return;
    }

    if (prop("typeahead") && isTypeaheadKey(key)) {
      event.preventDefault();
      send({ type: "TYPEAHEAD.KEY", key });
    }
  }

  function onContentKeyUp(event: KeyboardEvent): void {
    if (event.defaultPrevented || event.key !== " ") return;
    if (event.ctrlKey || event.metaKey || event.altKey) return;
    event.preventDefault();
    send({ type: "ITEM.ACTIVATE" });
  }

  /**
   * The shape shared by `item`, `optionItem` and `triggerItem`. The three differ in
   * their role and in what opens, never in their geometry — which is why the sheet
   * can say `:is([data-part~="menu:item"], [data-part~="menu:trigger-item"])`.
   */
  function itemProps(item: MenuItemProps, role: string): HTMLProps {
    const itemDisabled = disabled || item.disabled === true;
    const highlighted = !itemDisabled && highlightedValue === item.value;

    return {
      id: getItemId(scope, item.value),
      role,
      // Roving: exactly one stop in the tab order, and it is the highlighted item.
      // Never `aria-activedescendant` — the focus is real (règle dure).
      tabIndex: highlighted ? 0 : -1,
      "aria-disabled": ariaAttr(itemDisabled),
      "aria-keyshortcuts": item.shortcut,
      "aria-describedby":
        item.description === true ? getItemDescriptionId(scope, item.value) : undefined,
      "data-value": item.value,
      "data-label": item.label,
      "data-highlighted": dataAttr(highlighted),
      "data-disabled": dataAttr(itemDisabled),
      "data-destructive": dataAttr(item.destructive),
      "data-highlighted-flash": dataAttr(flashingValue === item.value),
      // On the highlighted item only: the composite has one focus, and an attribute
      // claiming otherwise on every item describes nothing. No `data-focus-visible`
      // beside it — architecture.md makes the source the single truth and the ring
      // derives from it in the sheet, so a second attribute would be a live mirror
      // with nothing to keep it honest.
      "data-focus-source": highlighted ? (focusSource ?? undefined) : undefined,
      onPointerMove(event) {
        // A touch `pointermove` is a scroll or the start of a long press, never a
        // hover: taking it would highlight whatever the finger passes over.
        if (event.pointerType === "touch" || itemDisabled) return;
        send({
          type: "ITEM.POINTERMOVE",
          value: item.value,
          x: event.clientX,
          y: event.clientY,
        });
      },
      onPointerLeave(event) {
        if (event.pointerType === "touch") return;
        send({ type: "ITEM.POINTERLEAVE", value: item.value });
      },
    };
  }

  return {
    open,
    presentation,
    placement,
    highlightedValue,
    isSubmenu,
    triggerId,
    contentId,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    setHighlightedValue(value: string | null): void {
      send({ type: "HIGHLIGHT.SET", value });
    },

    closeTree(): void {
      send({ type: "TREE.CLOSE" });
    },

    setParent(parent: Service<MenuSchema> | null): void {
      send({ type: "PARENT.SET", parent });
    },

    setChild(child: Service<MenuSchema> | null): void {
      send({ type: "CHILD.SET", child });
    },

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: triggerId,
        type: "button",
        disabled,
        "aria-haspopup": "menu",
        "aria-expanded": boolAttr(open),
        // Only while open — a dangling IDREF names nothing.
        "aria-controls": open ? contentId : undefined,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
        "data-placement": placement,
        onPointerDown(event) {
          if (event.defaultPrevented || disabled || !isPrimaryPointer(event)) return;
          // Touch waits for the click: a menu that opened under a finger would
          // swallow the tap that was meant to reach the button.
          if (event.pointerType === "touch") return;
          send({ type: "TRIGGER.POINTERDOWN" });
        },
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
        onKeyDown(event) {
          if (event.defaultPrevented || disabled || isComposingEvent(event)) return;
          if (event.ctrlKey || event.metaKey || event.altKey) return;
          const action = getTriggerOpenAction(event.key);
          if (action === null) return;
          // Prevented for two reasons at once: the arrows must not scroll the page,
          // and Enter or Space on a real `<button>` would otherwise synthesise a
          // click that `toggleMenu` would read as a second press.
          event.preventDefault();
          // Space opens on keyup, and that is not a stylistic reading of the APG
          // split — it is what stops the key press leaking into the surface it
          // opens. Space's keyup lands on whatever holds the focus *then*, and by
          // then the menu is open with its first item focused, so opening on
          // keydown would activate that item the instant it appeared.
          if (event.key !== " ") send({ type: "TRIGGER.KEYDOWN", action });
        },
        onKeyUp(event) {
          if (event.defaultPrevented || disabled || event.key !== " ") return;
          if (event.ctrlKey || event.metaKey || event.altKey) return;
          event.preventDefault();
          send({ type: "TRIGGER.KEYDOWN", action: "first" });
        },
      }),

    /**
     * Any container. It carries no handler: the `contextmenu` listener and the long
     * press are installed natively by `trackContextTrigger`, because they have to be
     * listening while the surface is closed and must not be routed through an
     * adapter's synthetic system.
     */
    getContextTriggerProps: (): T["element"] =>
      normalize.element({
        ...parts.contextTrigger.attrs,
        id: getContextTriggerId(scope),
        // Programmatically focusable, never in the tab order: this part *is* the
        // anchor, so it has to be able to take the focus back when the surface
        // goes. A right mousedown blurs whatever was focused before the machine
        // ever sees the gesture, so `captureFinalFocus` reads BODY and stores
        // `null`, and the documented fallback — `getAnchorEl` — is this node.
        // Without a tabindex `focusElement` was a silent no-op on it and the focus
        // fell to BODY when the portal unmounted (WCAG 2.4.3). `tabindex="-1"` puts
        // the node in `FOCUSABLE_SELECTOR` without entering `getTabbables`, which
        // keeps only what the engine's `isTabbable` admits: the Tab order is unchanged.
        tabIndex: -1,
        // `aria-haspopup` is a global property and legal on anything. `aria-expanded`
        // is NOT — it is allowed only on a handful of roles, and this part is a bare
        // container the consumer brings, which maps to `generic`. Emitting it raised
        // an `aria-allowed-attr` violation on the one element the whole context-menu
        // preset is built from, and the React suite was staying green by excluding
        // the region from its axe run. The state is still readable: `data-state` is
        // the styling contract, and the surface itself carries the ARIA.
        "aria-haspopup": "menu",
        "data-state": state,
        "data-disabled": dataAttr(disabled),
      }),

    getIndicatorProps: (): T["element"] =>
      normalize.element({
        ...parts.indicator.attrs,
        id: getIndicatorId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-placement": placement,
      }),

    getBackdropProps: (): T["element"] =>
      normalize.element({
        ...parts.backdrop.attrs,
        id: getBackdropId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-presentation": presentation,
      }),

    /**
     * The floating element. **`data-side` and `data-align` are deliberately absent
     * here** — the position effect writes them onto this node directly, and an
     * adapter that also rendered them would fight the effect over the same two
     * attributes on every commit. They are published on `content` instead, from
     * `currentPlacement`, which is the same value one step later.
     */
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-sui-layer-parent": prop("parentId"),
        "data-state": state,
        "data-presentation": presentation,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: contentId,
        role: "menu",
        dir: context.get("surfaceDir") ?? dir,
        tabIndex: -1,
        "aria-orientation": "vertical",
        // Never both: the trigger names it when there is one, and a submenu's
        // trigger item *is* its trigger — `getTriggerItemProps` gives that node the
        // child's own trigger id precisely so this IDREF resolves.
        //
        // **And only when a trigger was really rendered.** A menu composed with
        // `getContextTriggerProps` alone has none, so this pointed at an id nobody
        // wrote — a dangling IDREF, which names nothing and which axe reports as
        // `incomplete` rather than as a violation. Unnamed is the better failure,
        // and `trackParts` says so in dev.
        "aria-labelledby": prop("label") === undefined && hasTrigger ? triggerId : undefined,
        "aria-label": prop("label"),
        "data-state": state,
        "data-presentation": presentation,
        "data-side": side,
        "data-align": align,
        "data-placement": placement,
        "data-has-selection": dataAttr(hasSelection),
        // Both gutters are decisions of the container, never of a row: the
        // axes are named for the menu, and the alignment they buy is *between*
        // rows. Published here so one row without a glyph cannot slide its label
        // left of the one above it.
        "data-has-symbols": dataAttr(hasSymbols),
        "data-level": String(level),
        // The surface applies the glass material, so the surface is what
        // owes its contents the on-glass palette (architecture.md).
        "data-sui-on-glass": "",
        "data-snav": "container",
        "data-snav-enter": "first",
        "data-snav-wrap": prop("loopFocus") ? "y" : undefined,
        // Confinement is declared here rather than by trapping the intent scope: a
        // trapped scope silences the spatial engine at the bottom of the stack and
        // makes the menu's own interior unreachable to a d-pad.
        "data-snav-trap": prop("modal") ? "" : undefined,
        onKeyDown: onContentKeyDown,
        onKeyUp: onContentKeyUp,
      }),

    getItemGroupProps: (group: MenuItemGroupProps): T["element"] =>
      normalize.element({
        ...parts.itemGroup.attrs,
        id: getItemGroupId(scope, group.id),
        role: "group",
        // Declared, not assumed — same shape as `description` on an item. Written
        // unconditionally it left every group without a rendered label holding a
        // dead IDREF *and* no accessible name at once.
        "aria-labelledby": group.label === true ? getItemGroupLabelId(scope, group.id) : undefined,
        // `horizontal` is reserved for the iOS Control Group, which is out of scope
        // for this version: the attribute exists now so adding it later costs no
        // machine change.
        "data-orientation": group.orientation ?? "vertical",
      }),

    // Not `role="presentation"`: it is referenced by the group's `aria-labelledby`,
    // and a presentational node names nothing.
    getItemGroupLabelProps: (label: MenuItemGroupLabelProps): T["element"] =>
      normalize.element({
        ...parts.itemGroupLabel.attrs,
        id: getItemGroupLabelId(scope, label.htmlFor),
      }),

    getItemProps: (item: MenuItemProps): T["element"] =>
      normalize.element({
        ...parts.item.attrs,
        ...itemProps(item, "menuitem"),
        onClick(event) {
          if (event.defaultPrevented || disabled || item.disabled === true) return;
          send({ type: "ITEM.CLICK", value: item.value, closeOnSelect: item.closeOnSelect });
        },
      }),

    getOptionItemProps: (item: MenuOptionItemProps): T["element"] =>
      normalize.element({
        ...parts.item.attrs,
        ...itemProps(item, item.type === "radio" ? "menuitemradio" : "menuitemcheckbox"),
        "aria-checked": boolAttr(item.checked),
        "data-checked": dataAttr(item.checked),
        onClick(event) {
          if (event.defaultPrevented || disabled || item.disabled === true) return;
          // The consumer owns the value; the menu only reports the flip. Reached by
          // the keyboard too, because `ITEM.ACTIVATE` clicks the element rather
          // than shortcutting past it.
          item.onCheckedChange?.(item.checked !== true);
          send({ type: "ITEM.CLICK", value: item.value, closeOnSelect: item.closeOnSelect });
        },
      }),

    /**
     * The parent's item and the child's trigger, on one node and under one part
     * token. It takes the **child's** trigger id, which is what makes the child's
     * `aria-labelledby` resolve and what gives its positioner an anchor without
     * anybody rendering a second element.
     */
    getTriggerItemProps: (child: MenuApi<T>, item: MenuItemProps): T["element"] =>
      normalize.element({
        ...parts.triggerItem.attrs,
        ...itemProps(item, "menuitem"),
        id: child.triggerId,
        "aria-haspopup": "menu",
        "aria-expanded": boolAttr(child.open),
        "aria-controls": child.open ? child.contentId : undefined,
        "data-state": child.open ? "open" : "closed",
        onClick(event) {
          if (event.defaultPrevented || disabled || item.disabled === true) return;
          // Named, because a tap and a synthetic click arrive with no `pointermove`
          // before them and therefore no highlight for the guard to read.
          send({ type: "CHILD.OPEN", focus: true, value: item.value });
        },
      }),

    // The reserved symbol column. Decoration:
    // the name comes from `itemText`.
    getItemSymbolProps: (): T["element"] =>
      normalize.element({ ...parts.itemSymbol.attrs, "aria-hidden": ariaAttr(true) }),

    getItemTextProps: (): T["element"] => normalize.element({ ...parts.itemText.attrs }),

    getItemDescriptionProps: (description: MenuItemDescriptionProps): T["element"] =>
      normalize.element({
        ...parts.itemDescription.attrs,
        id: getItemDescriptionId(scope, description.value),
      }),

    // The checkmark. The state is carried by `aria-checked` on the item, never by
    // the glyph — so this node is hidden and the two can never disagree.
    getItemIndicatorProps: (indicator: MenuItemIndicatorProps): T["element"] =>
      normalize.element({
        ...parts.itemIndicator.attrs,
        "aria-hidden": ariaAttr(true),
        "data-checked": dataAttr(indicator.checked),
      }),

    // A `<kbd>`, and hidden: the shortcut reaches assistive technology through
    // `aria-keyshortcuts` on the item, where it is a machine-readable string
    // rather than a row of glyphs.
    getItemShortcutProps: (): T["element"] =>
      normalize.element({ ...parts.itemShortcut.attrs, "aria-hidden": ariaAttr(true) }),

    getSeparatorProps: (): T["element"] =>
      normalize.element({
        ...parts.separator.attrs,
        role: "separator",
        "aria-orientation": "horizontal",
        "data-orientation": "horizontal",
      }),

    // Added by the adapter in the `sheet` presentation (components.md §3). Its
    // accessible name is checked in dev by `trackParts`.
    //
    // `role="menuitem"` because it is drawn *inside* the surface, and a `role="menu"`
    // owns nothing but `menuitem`, `menuitemcheckbox`, `menuitemradio`, `group` and
    // `separator`: a bare button there is an `aria-required-children` violation, and
    // the sheet is the one presentation that renders one. It is also the honest
    // reading — cancelling is an action of the sheet, and iOS draws it as one.
    //
    // **And because it is a `menuitem`, it is an item.** It goes through the same
    // `itemProps` as every other row — roving tabindex, highlight, pointer
    // handlers — for the reason the role implies: the roving list is the only way
    // into this surface, so a `menuitem` outside it is a control that no keyboard
    // and no d-pad can reach. It was outside it until 2026-09-02, and `End` in the
    // sheet stopped one row short of the only button the sheet has. Its value is
    // namespaced (`CANCEL_VALUE`) rather than borrowed from the label, so a
    // consumer item called `cancel` cannot collide with it, and the id stays the
    // cancel trigger's — `itemProps` writes an item id that is overridden here.
    getCancelTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.cancelTrigger.attrs,
        ...itemProps({ value: CANCEL_VALUE }, "menuitem"),
        id: getCancelTriggerId(scope),
        type: "button",
        "data-state": state,
        "data-presentation": presentation,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CANCEL.CLICK" });
        },
      }),
  };
}

/**
 * **The item collection is read from the DOM, never held in context.** A menu is a
 * transient surface whose items are composition — five call sites, five different
 * lists (CDC parity M1) — and a machine that had to be *told* about its own
 * children goes out of sync the first time one is rendered conditionally.
 *
 * The reading itself is `collection/dom-collection`, shared with every composite
 * that will want the same thing (`select`, `listbox`, `combobox`, `tree`); what is
 * left here is the menu's own selectors and its ids.
 */

import {
  getItemLabel as domItemLabel,
  findItemByValue,
  queryItems,
} from "../../collection/dom-collection";
import { contains } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import { getDocumentEl, type Scope } from "../../machine/scope";

export { getItemValue, isItemDisabled } from "../../collection/dom-collection";

const COMPONENT = "menu";

/**
 * Written out rather than derived from `parts`: the anatomy builds the same
 * strings, and a component that imports its own anatomy into its DOM helpers pays
 * for the builder in every bundle that only wanted a query.
 */
const CONTENT_SELECTOR = '[data-part~="menu:content"]';
/**
 * The three identities of an item. `triggerItem` is a part of its own, and the
 * sheet's Cancel row is one too: it is drawn *inside* a `role="menu"`, so it
 * carries `role="menuitem"` — and a `menuitem` that the roving list does not know
 * about is a control no keyboard and no d-pad can reach. Excluded until
 * 2026-09-02, which made `End` in the sheet presentation stop one row short.
 */
export const ITEM_SELECTOR =
  '[data-part~="menu:item"], [data-part~="menu:trigger-item"], [data-part~="menu:cancel-trigger"]';

/**
 * The Cancel row's value in that collection. Namespaced rather than pretty: it
 * shares a `data-value` space with whatever the consumer names their own items,
 * and a menu with an item called `cancel` must not collide with it.
 */
export const CANCEL_VALUE = "sui:menu:cancel";
const TRIGGER_ITEM_SELECTOR = '[data-part~="menu:trigger-item"]';
const INDICATOR_SELECTOR = '[data-part~="menu:item-indicator"]';
const SYMBOL_SELECTOR = '[data-part~="menu:item-symbol"]';
const ITEM_TEXT_SELECTOR = '[data-part~="menu:item-text"]';

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getContextTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "context-trigger");
}

export function getIndicatorId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "indicator");
}

export function getBackdropId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "backdrop");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getItemGroupId(scope: Scope, key: string): string {
  return getPartId(scope, COMPONENT, "item-group", key);
}

export function getItemGroupLabelId(scope: Scope, key: string): string {
  return getPartId(scope, COMPONENT, "item-group-label", key);
}

export function getItemId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "item", value);
}

export function getItemDescriptionId(scope: Scope, value: string): string {
  return getPartId(scope, COMPONENT, "item-description", value);
}

export function getCancelTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "cancel-trigger");
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

export function getContextTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContextTriggerId(scope));
}

/**
 * What the surface measures itself against. The context trigger stands in when
 * there is no button — a right click anchors to the region — and a submenu's
 * anchor falls out of this for free, because `getTriggerItemProps` gives the
 * trigger item the **child's** trigger id.
 */
export function getAnchorEl(scope: Scope): HTMLElement | null {
  return getTriggerEl(scope) ?? getContextTriggerEl(scope);
}

/**
 * The anchor for the *direction* alone, which has one more fallback than the one
 * for geometry: a menu opened from a store renders neither trigger nor context
 * trigger, and resolving against nothing answers `"ltr"` flat — the one direction
 * an RTL page did not ask for. Never folded into `getAnchorEl`: that one is also
 * the element `trackPosition` measures, and the document would anchor the surface
 * to the whole page.
 */
export function getDirAnchorEl(scope: Scope): HTMLElement | null {
  return getAnchorEl(scope) ?? getDocumentEl(scope);
}

export function getBackdropEl(scope: Scope): HTMLElement | null {
  return scope.getById(getBackdropId(scope));
}

/** The floating element: what gets the translate, never the content. */
export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

export function getCancelTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getCancelTriggerId(scope));
}

/**
 * This menu's own items, in DOM order. The container filter is what a flat query
 * cannot do: in the `sheet` presentation a submenu is *drilled in* rather than
 * cascaded, so a child's `content` is stacked inside its parent's surface and its
 * items would otherwise join the parent's roving list.
 */
export function getItemEls(scope: Scope): HTMLElement[] {
  return queryItems(getContentEl(scope), ITEM_SELECTOR, CONTENT_SELECTOR);
}

export function isTriggerItem(item: HTMLElement): boolean {
  return item.matches(TRIGGER_ITEM_SELECTOR);
}

export function getItemLabel(item: HTMLElement): string {
  return domItemLabel(item, ITEM_TEXT_SELECTOR);
}

export function getItemEl(scope: Scope, value: string): HTMLElement | null {
  return findItemByValue(getItemEls(scope), value);
}

/**
 * Whether **this** surface draws a part, through the same container filter
 * `getItemEls` uses — and for the same reason, which both gutter reads below were
 * missing until 2026-09-02. A bare `querySelector` descends into a drilled-in
 * child, so in the `sheet` presentation a parent with no glyph of its own inherited
 * one from its submenu and opened a 28px column for it on every row, then handed it
 * back when the child closed.
 */
function ownsPart(scope: Scope, selector: string): boolean {
  return queryItems(getContentEl(scope), selector, CONTENT_SELECTOR).length > 0;
}

/**
 * The selection axis is named for the **menu**:
 * the checkmark gutter is a decision of the container, so it is read once for the
 * surface and published on `content`, never on an item.
 */
export function hasSelectionGutter(scope: Scope): boolean {
  return ownsPart(scope, INDICATOR_SELECTOR);
}

/**
 * Whether any row draws a glyph — and therefore whether the symbol track is
 * reserved for **all** of them. Read once for the surface, exactly like the
 * checkmark gutter above, because the alignment it buys is between rows: each row
 * is its own grid, so a track sized from its own content collapses on every row
 * without a symbol and slides that row's label left of its neighbours'.
 */
export function hasSymbolGutter(scope: Scope): boolean {
  return ownsPart(scope, SYMBOL_SELECTOR);
}

/** Whether the real focus is inside this menu's surface — never a virtual one. */
export function ownsFocus(scope: Scope): boolean {
  return contains(getContentEl(scope), scope.getActiveElement());
}

/** Same three fallbacks as the dialog: no document, no throw. */
export function getEnvironmentEl(scope: Scope): HTMLElement | null {
  return getContentEl(scope) ?? getAnchorEl(scope) ?? getDocumentEl(scope);
}

/**
 * The key table, pure and DOM-free, so the RTL mirror can be asserted in the node
 * project and so `connect` and the intent scope resolve a direction exactly once.
 *
 * `getRovingKeyAction` already owns the mirror for the axis a composite navigates
 * (architecture.md: "le miroir vit dans `getRovingKeyAction`, une fois par
 * composite"), and a vertical menu therefore gets `null` from it for both
 * horizontal arrows. What is left is the *other* horizontal meaning a menu has —
 * open a submenu, close a level — and it needs the same mirror, once, here.
 */

import type { RovingAction } from "../../focus/roving-focus";
import type { Direction, NavigationIntent } from "../../types";

export type MenuSubmenuAction = "open" | "close";

/**
 * `fwd` opens, `back` closes. `fwd` is ArrowRight in LTR and ArrowLeft in RTL —
 * the physical key, mirrored once, exactly like the roving axis.
 */
export function getSubmenuKeyAction(key: string, dir: Direction): MenuSubmenuAction | null {
  const rtl = dir === "rtl";
  if (key === "ArrowRight") return rtl ? "close" : "open";
  if (key === "ArrowLeft") return rtl ? "open" : "close";
  return null;
}

/**
 * The gamepad half. `moveLeft`/`moveRight` are physical intents by contract — the
 * keymap holds no mirror — so they are translated into their keys and answered by
 * the same function. One rule, two sources, which is the founding invariant.
 */
export function getSubmenuIntentAction(
  intent: NavigationIntent,
  dir: Direction,
): MenuSubmenuAction | null {
  if (intent === "moveRight") return getSubmenuKeyAction("ArrowRight", dir);
  if (intent === "moveLeft") return getSubmenuKeyAction("ArrowLeft", dir);
  return null;
}

/**
 * PageUp/PageDown are first/last in a menu, which `getRovingKeyAction` has no
 * opinion about — it speaks Home and End. Folding the pair onto those two keeps
 * one table rather than two, and keeps the gamepad's LT/RT on the same path.
 */
export function toRovingKey(key: string): string {
  if (key === "PageUp") return "Home";
  if (key === "PageDown") return "End";
  return key;
}

/** The intents that move the highlight, expressed as the keys they are twins of. */
export function toRovingIntentKey(intent: NavigationIntent): string | null {
  switch (intent) {
    case "moveUp":
      return "ArrowUp";
    case "moveDown":
      return "ArrowDown";
    case "home":
    case "pageUp":
      return "Home";
    case "end":
    case "pageDown":
      return "End";
    default:
      return null;
  }
}

/**
 * Which end of the menu a key on the **trigger** opens onto (APG Menu Button):
 * Enter, Space and ArrowDown land on the first item, ArrowUp on the last.
 */
export function getTriggerOpenAction(key: string): RovingAction | null {
  if (key === "Enter" || key === " " || key === "ArrowDown") return "first";
  if (key === "ArrowUp") return "last";
  return null;
}

/**
 * A menu is the first surface in the library that is an overlay **and** a
 * collection, and every decision below comes from refusing to pay twice for that.
 *
 * **Two states, not four.** `context.open` is the only source of truth and the
 * state is a projection of it — the dialog's and the popover's decision, kept
 * verbatim. The submenu delays are famously modelled as `opening`/`closing`
 * elsewhere; they are not states here, because a state that `open` does not
 * project would break the controlled path the moment a consumer drives `open`
 * from outside. They live in timers that `trackPointerIntent` owns and releases.
 *
 * **The order the effects install in is a contract**, because the interpreter
 * tears down in reverse: `trackAnchorPosition` runs before anything that moves
 * the focus, for the popover's exact reason — a focus landing in a surface still
 * parked at `0,0` makes the browser scroll the page there to reveal it.
 *
 * **Nothing about the item list is in context.** It is read from the live DOM
 * (`menu.dom.ts`), so there is no `isEqual`, no ordering to synchronise and no
 * registry a consumer has to maintain.
 *
 * **The value of an option item is not the menu's either.** `getOptionItemProps`
 * is controlled by the consumer — a divergence from `radio-group`, and a
 * deliberate one: a menu is transient and unmounts, so the checked state belongs
 * to the model behind it.
 */

import { hasAccessibleName } from "../../a11y/accessible-name";
import { hideOthers } from "../../a11y/aria-hidden";
import { lockScroll } from "../../a11y/scroll-lock";
import { getItemValue, getNextItem, isItemDisabled } from "../../collection/dom-collection";
import { addDomEvent } from "../../dom/event";
import { observeChildren } from "../../dom/observers";
import { contains } from "../../dom/query";
import { timeout } from "../../dom/raf";
import { resolveDir } from "../../dom/text-dir";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { proxyTabFocus } from "../../focus/proxy-tab-focus";
import { restoreFocus } from "../../focus/restore-focus";
import { getRovingKeyAction, type RovingAction } from "../../focus/roving-focus";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack, isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { trackLongPress } from "../../interaction/long-press";
import { isPointerHeadingTo, pushTrail } from "../../interaction/safe-triangle";
import { trackScrollEdges as trackEdges } from "../../interaction/scroll-edges";
import { createTypeaheadState, getByTypeahead } from "../../interaction/typeahead";
import { createMachine } from "../../machine/create-machine";
import type { Machine, MachineParams, Transition } from "../../machine/types";
import { focusElement, getInputModality, trackInputModality } from "../../nav";
import { trackPosition } from "../../positioner/track-position";
import type { Density, Direction, InputModality, Rect } from "../../types";
import { isDev } from "../../utils/env";
import { warn } from "../../utils/invariant";
import {
  getAnchorEl,
  getBackdropEl,
  getCancelTriggerEl,
  getContentEl,
  getContentId,
  getContextTriggerEl,
  getDirAnchorEl,
  getEnvironmentEl,
  getItemEl,
  getItemEls,
  getItemLabel,
  getPositionerEl,
  getTriggerEl,
  getTriggerId,
  hasSelectionGutter,
  hasSymbolGutter,
  isTriggerItem,
  ownsFocus,
} from "./menu.dom";
import { getSubmenuIntentAction, toRovingIntentKey } from "./menu.keys";
import type { MenuSchema } from "./menu.types";

type Params = MachineParams<MenuSchema>;

/** The inline properties `trackPosition` writes and never cleans up itself. */
const POSITION_STYLES = ["position", "top", "left", "transform", "width"] as const;

/**
 * `2 × --sui-duration-75`, the selection blink. A number rather than a read
 * of the custom property: the machine must not depend on a stylesheet being
 * loaded, and the deferral it buys the close is a behaviour, not a decoration.
 */
const FLASH_DURATION_MS = 150;

/**
 * How long after an opening press a click on the same trigger is *not* a toggle.
 * Press-drag-release: the pointer goes down, the menu opens, and the release that
 * follows on the trigger must leave it open.
 */
const REOPEN_GRACE_MS = 300;

/**
 * How long the swallow of a dismissing click stays armed. A trusted click follows
 * its own pointerup within a frame; the fuse exists only so a gesture that ended in
 * a drag cannot leave a listener behind waiting for a click nobody meant.
 */
const CLICK_SWALLOW_MS = 300;

const ZERO_RECT: Rect = { x: 0, y: 0, width: 0, height: 0 };

/**
 * Where a submenu goes when `right-start` does not fit. Sideways first — that is
 * what keeps it clear of the surface it came out of, and it is what
 * native menus draw — and only then off the axis, under or over the row that opened it.
 *
 * Leaving the axis is free here and nowhere else: the anchor **is** the row
 * (`getTriggerItemProps` gives the parent's row the child's trigger id), so
 * `bottom-start` already means "under this item, aligned to its leading edge".
 *
 * A root menu passes nothing and keeps the single-opposite flip it always had.
 */
const SUBMENU_FALLBACKS = ["left-start", "bottom-start", "top-start"] as const;

function windowOf({ scope }: Params): (Window & typeof globalThis) | null {
  return getContentEl(scope)?.ownerDocument.defaultView ?? null;
}

function childContentRect({ refs }: Params): Rect | null {
  const child = refs.get("child");
  if (child === null) return null;
  const content = getContentEl(child.scope);
  if (content === null) return null;
  const { x, y, width, height } = content.getBoundingClientRect();
  return { x, y, width, height };
}

function cancelIntent({ refs }: Params): void {
  refs.get("intentTimer")?.();
  refs.set("intentTimer", null);
}

/** The one place `highlightedValue` is written, so the modality is never forgotten. */
function commitHighlight(params: Params, value: string | null): void {
  const { context, scope } = params;
  if (scope.getRootNode() !== null) {
    context.set("focusSource", value === null ? null : getInputModality(scope.getDoc()));
  }
  context.set("highlightedValue", value);
}

/**
 * The focus is real, always: roving `tabindex` and a `.focus()` on the highlighted
 * item, never `aria-activedescendant` (règle dure — "la manette pilote le vrai
 * focus DOM"). `data-focus-source` is what keeps the ring off under a pointer.
 */
function focusHighlightedItem({ context, scope }: Params): void {
  const value = context.get("highlightedValue");
  if (value === null) return;
  const item = getItemEl(scope, value);
  focusElement(item);
  if (item === null) return;

  // **The focus moved and the surface never did.** `focusElement` asks for
  // `preventScroll: true` — right, because the ring must not make the page jump —
  // but that also suppresses the user agent's own reveal, and nothing here put it
  // back. Past the seventh row of a capped menu the highlighted item was outside
  // its own surface, so a keyboard or a d-pad could not reach the tail of a long
  // menu at all: WCAG 2.2 §2.4.11, against the AA floor of CDC §5.2. The guard is
  // `tabs`', and so is the motion resolution — attributes before media queries.
  const content = getContentEl(scope);
  if (content === null || content.scrollHeight <= content.clientHeight) return;
  item.scrollIntoView({
    block: "nearest",
    inline: "nearest",
    behavior: resolveEnvironment(content).reducedMotion ? "auto" : "smooth",
  });
}

/**
 * Disabled items are stepped over rather than focused: APG allows either, and the
 * library already chose skipping in `radio-group` and `toggle-group`.
 */
function applyRoving(params: Params, action: RovingAction): void {
  const { context, prop, scope } = params;
  const target = getNextItem(
    getItemEls(scope),
    context.get("highlightedValue"),
    action,
    prop("loopFocus"),
  );
  if (target !== null) commitHighlight(params, getItemValue(target));
}

function openSurface(params: Params): void {
  const { context, refs, event } = params;
  if (event.type === "TRIGGER.KEYDOWN") refs.set("pendingHighlight", event.action);
  if (event.type === "TRIGGER.CONTEXTMENU" || event.type === "TRIGGER.LONGPRESS") {
    refs.set("pendingHighlight", "first");
  } else {
    // A menu opened from its button anchors to the button, whatever a previous
    // right click left behind.
    refs.set("anchorPoint", null);
  }
  refs.set("openedAt", Date.now());
  context.set("open", true);
}

function selectedValue(params: Params): string | null {
  const { event } = params;
  if (event.type === "ITEM.CLICK" || event.type === "ITEM.SELECT") return event.value;
  return null;
}

function selectedItem(params: Params): HTMLElement | null {
  const value = selectedValue(params);
  return value === null ? null : getItemEl(params.scope, value);
}

/**
 * The item an event *names*, which is one more than the item it selects: a hover
 * names one too, and the guard that lets a hover through has to be able to see it.
 * Reading `selectedItem` there answered `null` for every `ITEM.POINTERMOVE`, so the
 * guarded branch never ran — no highlight under the pointer, and no submenu ever
 * armed — while the unguarded fallback recorded the trail and made it look alive.
 */
function eventItem(params: Params): HTMLElement | null {
  const { event, scope } = params;
  if (event.type === "ITEM.POINTERMOVE") return getItemEl(scope, event.value);
  return selectedItem(params);
}

function closesOnSelect(params: Params): boolean {
  const { event, prop } = params;
  if (event.type !== "ITEM.CLICK" && event.type !== "ITEM.SELECT") return false;
  return event.closeOnSelect ?? prop("closeOnSelect");
}

/**
 * Whether the one child slot belongs to the item the highlight is on.
 *
 * The machine holds a **single** child, and the adapter hands that slot to
 * whichever submenu the highlight sits on. Without this, `CHILD.OPEN` arriving
 * from a plain item opened the *neighbour's* submenu — anchored to a row the
 * highlight was nowhere near, which is what `ArrowRight` on a non-trigger item
 * did until 2026-09-02.
 *
 * Answered from the DOM rather than from a ref, and that is not a shortcut: a
 * trigger item **is** the child's trigger, `getTriggerItemProps` gives that node
 * the child's own trigger id by construction, so the id is the link.
 */
function ownsChildSlot(params: Params): boolean {
  const { context, event, refs, scope } = params;
  const child = refs.get("child");
  if (child === null) return false;
  // A click names its own item: a touch tap and a synthetic `.click()` both reach
  // the trigger item with no `pointermove` ahead of them, so there is no highlight
  // to read and the highlight would refuse a perfectly good request. Everything
  // else — the arrow, the d-pad, the hover timer — is about the highlight.
  const named = event.type === "CHILD.OPEN" ? event.value : undefined;
  const value = named ?? context.get("highlightedValue");
  if (value === null || value === undefined) return false;
  const item = getItemEl(scope, value);
  if (item === null || !isTriggerItem(item)) return false;
  return item.id === getTriggerId(child.scope);
}

/**
 * Four branches, one array, two event names. `ITEM.CLICK` is what the element's
 * own handler sends and `ITEM.SELECT` is the programmatic twin; they resolve
 * identically, so they share the list rather than restating it.
 */
const SELECT_TRANSITIONS: Transition<MenuSchema> = [
  { guard: "isTriggerItem", actions: ["openChild"] },
  { guard: "shouldFlash", actions: ["invokeOnSelect", "flashSelection"] },
  { guard: "shouldCloseOnSelect", actions: ["invokeOnSelect", "closeTree"] },
  { guard: "isItemEnabled", actions: ["invokeOnSelect"] },
];

export const machine: Machine<MenuSchema> = createMachine<MenuSchema>({
  props({ props }) {
    return {
      defaultOpen: false,
      presentation: "auto",
      // No `placement` default: which of `bottom-start` and `right-start` applies
      // is only known once a parent has been wired, so it is a `computed`.
      gap: 4,
      offset: 0,
      flip: true,
      shift: true,
      padding: 8,
      matchWidth: false,
      strategy: "fixed",
      // Native desktop menus wrap. So does the d-pad, through `data-snav-wrap="y"`.
      loopFocus: true,
      typeahead: true,
      closeOnSelect: true,
      closeOnEscape: true,
      closeOnInteractOutside: true,
      preventOutsideActivation: true,
      modal: false,
      autoFocus: true,
      restoreFocus: true,
      submenuOpenDelay: 100,
      submenuCloseDelay: 250,
      selectionFlash: true,
      disabled: false,
      intents: null,
      ...props,
    };
  },

  context({ prop, bindable }) {
    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "menu open",
      })),
      density: bindable<Density>(() => ({ defaultValue: "desktop" })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
      // Seeded from the props rather than from a constant: the server renders
      // `data-side` from this, and the first paint has to agree with the markup.
      // `parentId` is the only submenu hint available before `PARENT.SET` lands.
      currentPlacement: bindable(() => ({
        defaultValue:
          prop("placement") ?? (prop("parentId") === undefined ? "bottom-start" : "right-start"),
      })),
      highlightedValue: bindable<string | null>(() => ({
        defaultValue: prop("defaultHighlightedValue") ?? null,
        value: prop("highlightedValue"),
        onChange: (value) => prop("onHighlightChange")?.({ value }),
        debugLabel: "menu highlightedValue",
      })),
      hasSelectionGutter: bindable<boolean>(() => ({ defaultValue: false })),
      hasSymbolGutter: bindable<boolean>(() => ({ defaultValue: false })),
      hasTrigger: bindable<boolean>(() => ({ defaultValue: false })),
      hasParent: bindable<boolean>(() => ({ defaultValue: false })),
      flashingValue: bindable<string | null>(() => ({ defaultValue: null })),
      focusSource: bindable<InputModality | null>(() => ({ defaultValue: null })),
    };
  },

  computed: {
    presentation({ prop, context, refs }) {
      const requested = prop("presentation");
      if (requested !== "auto") return requested;
      // **It descends, and it did not until now.** A submenu is its own
      // `<MenuRoot>` with its own props, so `"auto"` resolved on the child's own
      // density and a sheet's submenu came out a `popup`: portalled, anchored
      // `right-start` on a row as wide as the sheet, and therefore a 13px ribbon
      // pinned to the screen edge with both its labels clipped to nothing. Read
      // live from the parent rather than copied at `PARENT.SET`, because `computed`
      // is deliberately not memoised — so a density flip at the root reaches every
      // level of the tree without an event, a context key or a second source of
      // truth to keep in step.
      const parent = refs.get("parent");
      if (parent !== null) return parent.computed("presentation");
      // Touch gets the sheet, which is the iOS action sheet, and with it the
      // drill-in submenus and the cancel button. One machine either way.
      return context.get("density") === "touch" ? "sheet" : "popup";
    },

    isSubmenu: ({ context, prop }) => context.get("hasParent") || prop("parentId") !== undefined,

    placement({ prop, context }) {
      const requested = prop("placement");
      if (requested !== undefined) return requested;
      const submenu = context.get("hasParent") || prop("parentId") !== undefined;
      return submenu ? "right-start" : "bottom-start";
    },
  },

  refs() {
    return {
      finalFocusEl: null,
      anchorPoint: null,
      parent: null,
      child: null,
      typeahead: createTypeaheadState(),
      intentTimer: null,
      flashTimer: null,
      pointerTrail: [],
      openedAt: 0,
      pendingHighlight: null,
    };
  },

  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackEnvironment", "trackModality", "trackContextTrigger"],

  watch({ context, computed, scope, track, send, action }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
    track(
      () => [computed("presentation")],
      () => send({ type: "PRESENTATION.SYNC" }),
    );
    track(
      () => [hasSelectionGutter(scope), hasSymbolGutter(scope), getTriggerEl(scope) !== null],
      () => action(["syncParts"]),
    );
  },

  on: {
    "TRIGGER.CLICK": { guard: "isEnabled", actions: ["toggleMenu"] },
    // A press on the trigger of a menu that is *already* open is the first half of
    // the click that closes it, so it opens nothing and — the part that matters —
    // must not refresh `openedAt`. Refreshing it put every second click inside the
    // press-drag-release grace, and a menu button that could not be closed by the
    // button is not a menu button (APG).
    "TRIGGER.POINTERDOWN": [{ guard: "isOpen" }, { guard: "isEnabled", actions: ["openMenu"] }],
    "TRIGGER.KEYDOWN": { guard: "isEnabled", actions: ["openMenu"] },
    "TRIGGER.CONTEXTMENU": { guard: "isEnabled", actions: ["setAnchorPoint", "openMenu"] },
    "TRIGGER.LONGPRESS": { guard: "isEnabled", actions: ["setAnchorPoint", "openMenu"] },

    // The safe triangle wins over the highlight: a pointer cutting diagonally
    // towards an open submenu must not re-aim the parent at whatever item it
    // happens to be crossing.
    "ITEM.POINTERMOVE": [
      { guard: "isPointerHeadingToChild", actions: ["recordPointer"] },
      {
        guard: "isItemEnabled",
        actions: ["recordPointer", "highlightItem", "focusHighlighted", "scheduleChild"],
      },
      { actions: ["recordPointer"] },
    ],
    "ITEM.POINTERLEAVE": [
      { guard: "isPointerHeadingToChild" },
      { actions: ["scheduleChildClose"] },
    ],

    "ITEM.CLICK": SELECT_TRANSITIONS,
    "ITEM.SELECT": SELECT_TRANSITIONS,
    // Enter, Space and the A button. It clicks the element rather than shortcutting
    // to `invokeOnSelect`, so a keyboard activation and a pointer one run exactly
    // the same handlers — which is what makes `onCheckedChange` and any consumer
    // handler on the item work without the machine knowing they exist.
    "ITEM.ACTIVATE": { actions: ["activateHighlighted"] },

    // `closeStaleChild` closes on the way out of a trigger item: the pointer path
    // has `ITEM.POINTERLEAVE` for that, these three had nothing.
    "HIGHLIGHT.MOVE": { actions: ["moveHighlight", "focusHighlighted", "closeStaleChild"] },
    // `null` clears it, which is why there is no second event for that.
    "HIGHLIGHT.SET": { actions: ["highlightItem", "focusHighlighted", "closeStaleChild"] },
    "TYPEAHEAD.KEY": {
      guard: "isTypeaheadEnabled",
      actions: ["typeaheadHighlight", "focusHighlighted", "closeStaleChild"],
    },

    "FLASH.END": { actions: ["clearFlash", "closeTree"] },

    // Guarded, because the slot is not always the highlight's. See
    // `highlightOwnsChild`: unguarded, ArrowRight on a plain item opened whichever
    // submenu happened to hold the slot.
    "CHILD.OPEN": { guard: "hasChildFor", actions: ["openChild"] },
    // One event, two readings, and they compose into the `back` grammar: close the
    // child if there is one open, otherwise close *this* level when it is itself a
    // submenu, otherwise do nothing at all.
    "CHILD.CLOSE": [
      { guard: "hasOpenChild", actions: ["closeChild", "focusHighlighted"] },
      { guard: "isSubmenu", actions: ["closeMenu"] },
    ],
    "CHILD.SET": { actions: ["setChild"] },
    "PARENT.SET": { actions: ["setParent"] },

    "CONTENT.DISMISS": { guard: "canDismiss", actions: ["invokeOnDismiss", "closeMenu"] },
    "TREE.CLOSE": { actions: ["closeTree"] },
    "CANCEL.CLICK": { actions: ["closeTree"] },

    "POSITION.SYNC": { actions: ["syncPlacement"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
    // The density flip tears the open state down and builds it back: the position
    // tracker leaves, the scroll lock arrives, the geometry changes.
    "PRESENTATION.SYNC": { guard: "isOpen", target: "open", reenter: true },
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
  },

  states: {
    closed: {
      // Downward cascade, and it recurses on its own: a child entering `closed`
      // closes its own child. Upward is `closeTree`.
      entry: ["closeChild"],
      // Exit rather than the open state's entry, for the dialog's reason: the
      // interpreter installs effects before entry actions, and `hideOutside`
      // makes the trigger's ancestor inert, which blurs it.
      exit: ["captureFinalFocus"],
    },
    open: {
      entry: ["highlightInitial"],
      effects: [
        "trackSurfaceDir",
        "trackDismissable",
        "lockPageScroll",
        // Before anything that moves the focus. A focus landing in a surface still
        // parked at `0,0` scrolls the page there to reveal it.
        "trackAnchorPosition",
        "focusContent",
        "proxyTabs",
        "hideOutside",
        "captureIntents",
        "trackPointerIntent",
        "trackSelectionFlash",
        "trackParts",
        // Last, and after `trackParts` on purpose: the gutter attributes that
        // effect publishes are what decide how tall a row is, so reading whether
        // the surface overflows before they land measures a layout nobody will see.
        "trackScrollEdges",
      ],
    },
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),
      isOpen: ({ context }) => context.get("open"),
      isSubmenu: ({ computed }) => computed("isSubmenu"),

      /** Read live from the props, never snapshotted into the layer at install. */
      canDismiss({ prop, event }) {
        if (event.type !== "CONTENT.DISMISS") return false;
        if (isEscapeLikeDismissal(event.reason)) return prop("closeOnEscape");
        return prop("closeOnInteractOutside");
      },

      isItemEnabled(params) {
        if (params.prop("disabled")) return false;
        const item = eventItem(params);
        return item !== null && !isItemDisabled(item);
      },

      isTriggerItem(params) {
        if (params.prop("disabled")) return false;
        const item = selectedItem(params);
        return item !== null && !isItemDisabled(item) && isTriggerItem(item);
      },

      isPointerHeadingToChild(params) {
        const { event, refs } = params;
        if (event.type !== "ITEM.POINTERMOVE" && event.type !== "ITEM.POINTERLEAVE") return false;
        const child = refs.get("child");
        if (child === null || !child.context.get("open")) return false;
        const trail =
          event.type === "ITEM.POINTERMOVE"
            ? pushTrail(refs.get("pointerTrail"), { x: event.x, y: event.y })
            : refs.get("pointerTrail");
        return isPointerHeadingTo(trail, childContentRect(params));
      },

      hasOpenChild: ({ refs }) => refs.get("child")?.context.get("open") === true,

      hasChildFor: ownsChildSlot,

      shouldCloseOnSelect(params) {
        if (params.prop("disabled")) return false;
        const item = selectedItem(params);
        if (item === null || isItemDisabled(item)) return false;
        return closesOnSelect(params);
      },

      /**
       * The blink only exists where it means something: a popup on a desktop that
       * is about to close. It is read here rather than in `connect` because
       * `matchMedia` is a platform read and `connect` is pure — and it goes
       * through `resolveEnvironment`, so an app pinned to `data-motion="full"`
       * keeps its blink and one pinned to `reduced` loses it.
       */
      shouldFlash(params) {
        const { prop, computed, scope } = params;
        if (prop("disabled") || !prop("selectionFlash")) return false;
        if (computed("presentation") !== "popup") return false;
        const item = selectedItem(params);
        if (item === null || isItemDisabled(item)) return false;
        if (!closesOnSelect(params)) return false;
        return !resolveEnvironment(getContentEl(scope)).reducedMotion;
      },

      isTypeaheadEnabled: ({ prop }) => prop("typeahead") && !prop("disabled"),
    },

    actions: {
      /**
       * The disclosure. `openedAt` is what makes press-drag-release work: the
       * click that lands on the trigger right after the press that opened the menu
       * is the *release*, not a second press, and closing there would make a menu
       * impossible to open with a normal click.
       */
      toggleMenu(params) {
        const { context, refs } = params;
        if (!context.get("open")) {
          openSurface(params);
          return;
        }
        const openedAt = refs.get("openedAt");
        if (openedAt !== 0 && Date.now() - openedAt < REOPEN_GRACE_MS) return;
        context.set("open", false);
      },

      openMenu: openSurface,

      /** This level only. `TREE.CLOSE` is the one that walks up. */
      closeMenu({ context }) {
        context.set("open", false);
      },

      /**
       * Up the chain, one hop at a time: each parent runs this same action, so a
       * three-deep tree closes in three sends and nothing has to know its depth.
       * Downwards is `closed.entry`, which cascades on its own.
       */
      closeTree({ context, refs }) {
        context.set("open", false);
        refs.get("parent")?.send({ type: "TREE.CLOSE" });
      },

      setOpen({ context, refs, event }) {
        if (event.type !== "OPEN.SET") return;
        if (event.open && event.highlight !== undefined) {
          refs.set("pendingHighlight", event.highlight);
        }
        context.set("open", event.open);
      },

      setAnchorPoint({ refs, event }) {
        if (event.type === "TRIGGER.CONTEXTMENU" || event.type === "TRIGGER.LONGPRESS") {
          refs.set("anchorPoint", { x: event.x, y: event.y });
        }
      },

      captureFinalFocus({ refs, scope }) {
        const active = scope.getActiveElement();
        refs.set("finalFocusEl", active === null || active.tagName === "BODY" ? null : active);
      },

      /**
       * Runs as the open state's **entry**, which the interpreter schedules after
       * the effects — and after the adapter has painted, because it is a `watch`
       * that flipped the state. So the content exists here, and a request the
       * keyboard made before it did (`pendingHighlight`) can finally be honoured.
       */
      highlightInitial(params) {
        const { refs, prop } = params;
        const pending = refs.get("pendingHighlight");
        refs.set("pendingHighlight", null);
        if (pending !== null) {
          applyRoving(params, pending);
          focusHighlightedItem(params);
          return;
        }
        const initial = prop("defaultHighlightedValue") ?? null;
        if (initial === null) return;
        commitHighlight(params, initial);
        focusHighlightedItem(params);
      },

      highlightItem(params) {
        const { event } = params;
        if (event.type === "ITEM.POINTERMOVE") {
          commitHighlight(params, event.value);
          return;
        }
        if (event.type === "HIGHLIGHT.SET") commitHighlight(params, event.value);
      },

      moveHighlight(params) {
        if (params.event.type === "HIGHLIGHT.MOVE") applyRoving(params, params.event.action);
      },

      focusHighlighted: focusHighlightedItem,

      typeaheadHighlight(params) {
        const { event, refs, scope, context } = params;
        if (event.type !== "TYPEAHEAD.KEY") return;
        const items = getItemEls(scope);
        const value = context.get("highlightedValue");
        const match = getByTypeahead(refs.get("typeahead"), event.key, {
          items,
          itemToString: getItemLabel,
          isItemDisabled,
          activeIndex: items.findIndex((item) => getItemValue(item) === value),
        });
        if (match !== null) commitHighlight(params, getItemValue(match));
      },

      recordPointer({ refs, event }) {
        if (event.type !== "ITEM.POINTERMOVE") return;
        refs.set("pointerTrail", pushTrail(refs.get("pointerTrail"), { x: event.x, y: event.y }));
      },

      /**
       * The submenu delay, and its counterpart. Hovering the item that owns a
       * submenu arms the open; hovering any other item arms the close of whatever
       * is already open — which is the only reason a cascade ever collapses under
       * a pointer that never leaves the menu.
       */
      scheduleChild(params) {
        const { prop, refs, scope, event, send } = params;
        if (event.type !== "ITEM.POINTERMOVE") return;
        cancelIntent(params);
        const win = windowOf(params);
        if (win === null) return;

        const item = getItemEl(scope, event.value);
        if (item !== null && isTriggerItem(item)) {
          if (refs.get("child")?.context.get("open") === true) return;
          refs.set(
            "intentTimer",
            timeout(win, () => send({ type: "CHILD.OPEN" }), prop("submenuOpenDelay")),
          );
          return;
        }
        if (refs.get("child")?.context.get("open") !== true) return;
        refs.set(
          "intentTimer",
          timeout(win, () => send({ type: "CHILD.CLOSE" }), prop("submenuCloseDelay")),
        );
      },

      /**
       * Armed, but re-checked when it fires. The pointer leaving a trigger item is
       * usually the pointer entering the submenu, and by then the focus has moved
       * in with it — so the timer asks before it closes anything.
       */
      scheduleChildClose(params) {
        const { prop, refs, send } = params;
        cancelIntent(params);
        const win = windowOf(params);
        if (win === null || refs.get("child")?.context.get("open") !== true) return;
        refs.set(
          "intentTimer",
          timeout(
            win,
            () => {
              refs.set("intentTimer", null);
              const child = refs.get("child");
              if (child === null) return;
              const content = getContentEl(child.scope);
              if (contains(content, child.scope.getActiveElement())) return;
              send({ type: "CHILD.CLOSE" });
            },
            prop("submenuCloseDelay"),
          ),
        );
      },

      activateHighlighted({ context, scope, prop }) {
        if (prop("disabled")) return;
        const value = context.get("highlightedValue");
        if (value === null) return;
        const item = getItemEl(scope, value);
        if (item === null || isItemDisabled(item)) return;
        item.click();
      },

      invokeOnSelect(params) {
        const value = selectedValue(params);
        if (value !== null) params.prop("onSelect")?.({ value });
      },

      /**
       * The blink owns the close: `FLASH.END` is what finally calls `closeTree`.
       * The timer is cancelled by `trackSelectionFlash`'s disposer — a menu closed
       * mid-blink would otherwise send `TREE.CLOSE` into a dead service.
       */
      flashSelection(params) {
        const { context, refs, send } = params;
        const value = selectedValue(params);
        if (value === null) return;
        refs.get("flashTimer")?.();
        context.set("flashingValue", value);
        const win = windowOf(params);
        if (win === null) {
          send({ type: "FLASH.END" });
          return;
        }
        refs.set(
          "flashTimer",
          timeout(
            win,
            () => {
              refs.set("flashTimer", null);
              send({ type: "FLASH.END" });
            },
            FLASH_DURATION_MS,
          ),
        );
      },

      clearFlash({ context, refs }) {
        refs.get("flashTimer")?.();
        refs.set("flashTimer", null);
        context.set("flashingValue", null);
      },

      openChild({ refs, event }) {
        const child = refs.get("child");
        if (child === null) return;
        // `highlight` rather than a second send: the child's content is not mounted
        // yet, so the request has to survive until its open state is entered.
        child.send({
          type: "OPEN.SET",
          open: true,
          highlight: event.type === "CHILD.OPEN" && event.focus === true ? "first" : undefined,
        });
      },

      closeChild({ refs }) {
        refs.get("child")?.send({ type: "OPEN.SET", open: false });
      },

      setChild({ refs, event }) {
        if (event.type === "CHILD.SET") refs.set("child", event.child);
      },

      setParent({ context, refs, event }) {
        if (event.type !== "PARENT.SET") return;
        refs.set("parent", event.parent);
        context.set("hasParent", event.parent !== null);
      },

      invokeOnDismiss({ prop, event }) {
        if (event.type === "CONTENT.DISMISS") prop("onDismiss")?.({ reason: event.reason });
      },

      syncEnvironment({ context, event }) {
        if (event.type === "ENVIRONMENT.SYNC") context.set("density", event.density);
      },

      syncPlacement({ context, event }) {
        if (event.type === "POSITION.SYNC") context.set("currentPlacement", event.placement);
      },

      syncParts({ context, scope }) {
        context.set("hasSelectionGutter", hasSelectionGutter(scope));
        context.set("hasSymbolGutter", hasSymbolGutter(scope));
        context.set("hasTrigger", getTriggerEl(scope) !== null);
      },

      /**
       * Moving the highlight off a trigger item closes what that item opened. The
       * pointer path already did it — `ITEM.POINTERLEAVE` schedules the close —
       * but the keyboard and the d-pad did not, so a submenu opened by a hover
       * survived an arrow key and stayed anchored to a row that was no longer
       * highlighted. Closing an already-closed child is a no-op, so this needs no
       * guard of its own beyond the ownership question.
       */
      closeStaleChild(params) {
        if (ownsChildSlot(params)) return;
        params.refs.get("child")?.send({ type: "OPEN.SET", open: false });
      },
    },

    effects: {
      trackEnvironment({ scope, send }) {
        const node = getEnvironmentEl(scope);
        const onChange = (density: Density): void => send({ type: "ENVIRONMENT.SYNC", density });
        onChange(resolveEnvironment(node).density);
        return watchEnvironment(node, {
          onChange: (environment) => onChange(environment.density),
        });
      },

      trackModality({ scope }) {
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      /**
       * Machine level, not open level: a context menu's opener has to be listening
       * while the surface is closed. `allowMouse: false` — on a pointer device the
       * gesture is a right click, and `threshold: 500` is the iOS delay.
       */
      trackContextTrigger({ prop, scope, send }) {
        const node = getContextTriggerEl(scope);
        if (node === null) return;
        const onContextMenu = (event: MouseEvent): void => {
          if (prop("disabled")) return;
          event.preventDefault();
          send({ type: "TRIGGER.CONTEXTMENU", x: event.clientX, y: event.clientY });
        };
        const removeContextMenu = addDomEvent(node, "contextmenu", onContextMenu);
        const removeLongPress = trackLongPress(node, {
          threshold: 500,
          allowMouse: false,
          isDisabled: () => prop("disabled"),
          onLongPress: (event) => send({ type: "TRIGGER.LONGPRESS", x: event.x, y: event.y }),
        });

        // **The keyboard and the pad, which had no opener at all until 2026-09-02.**
        // Shift+F10 and the pad's Y both arrive as the `contextMenu` intent and
        // neither produces a `contextmenu` event, so a region whose only opener was
        // the two listeners above could be reached by a mouse and by a finger and by
        // nothing else — WCAG 2.1.1 on the one gesture the part exists for. Pushed
        // here rather than in `captureIntents` because it has to answer while the
        // surface is *closed*, which is the same reason this whole effect is machine
        // level. The open menu's own scope sits above this one and deliberately
        // declines `contextMenu` (see `captureIntents`), so the two never race: when
        // the menu is open the focus is in the portalled content, `contains` is
        // false, and this scope declines too.
        //
        // Anchored on the focused element, since there is no pointer to anchor to —
        // its bottom edge, which is where a context menu opened from a row belongs.
        // A region with nothing focusable inside it stays mouse- and touch-only, and
        // that is correct: there is no focus for the gesture to be *about*.
        const host = prop("intents");
        const removeIntents =
          host === null || host === undefined
            ? (): void => {}
            : host.pushScope(
                (event) => {
                  if (event.intent !== "contextMenu" || prop("disabled")) return false;
                  const active = scope.getActiveElement();
                  if (active === null || !contains(node, active)) return false;
                  const rect = active.getBoundingClientRect();
                  send({
                    type: "TRIGGER.CONTEXTMENU",
                    x: rect.left + rect.width / 2,
                    y: rect.bottom,
                  });
                  return true;
                },
                { within: node },
              );

        return () => {
          removeIntents();
          removeLongPress();
          removeContextMenu();
        };
      },

      /**
       * Parity M5, and the whole of it: `preventOutsideActivation` makes the click
       * that closes a menu stop there instead of activating what was underneath —
       * the native behaviour, and the one the reference app's own context menu had. The pointer
       * default is suppressed *and* a one-shot capture listener eats the `click`
       * that the browser will still synthesise, because `preventDefault` on
       * `pointerdown` does not cancel it.
       *
       * **The swallow outlives this effect, and it has to.** The dismissal is
       * decided on the pointerup that follows, which tears the open state down —
       * so a listener the disposer took back off would be gone by the time the
       * click it exists for arrives, and the button underneath would fire. It
       * disarms itself on that click, and on a short fuse for the gesture that
       * ended in a drag and produced none.
       */
      trackDismissable({ prop, scope, send }) {
        const content = getContentEl(scope);
        const doc = content?.ownerDocument;
        const win = doc?.defaultView ?? null;

        return trackDismissableLayer(content, {
          id: getContentId(scope),
          type: "menu",
          modal: prop("modal"),
          // The stack already answers "does this node descend from that layer", so
          // a click inside a portalled submenu never dismisses its parent.
          parentId: prop("parentId"),
          exclude: () => [
            getTriggerEl(scope),
            getContextTriggerEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          onPointerDownOutside(event) {
            if (!prop("preventOutsideActivation") || doc === undefined || win === null) return;
            event.preventDefault();
            let cancelFuse: VoidFunction | undefined;
            const removeClick = addDomEvent(
              doc,
              "click",
              (click) => {
                click.preventDefault();
                click.stopPropagation();
                cancelFuse?.();
              },
              { capture: true, once: true },
            );
            cancelFuse = timeout(win, removeClick, CLICK_SWALLOW_MS);
          },
          onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
        });
      },

      lockPageScroll({ prop, computed, scope }) {
        if (computed("presentation") !== "sheet") return;
        if (prop("preventScroll") === false) return;
        return lockScroll(getContentEl(scope)?.ownerDocument);
      },

      /**
       * The sheet branch clears what a previous popup pass left behind, and it does
       * it **on install rather than on teardown**: cleaning up in the disposer
       * would run while `open` is going false with the node still mounted by
       * `presence`, and the surface would snap to `0,0` mid-exit.
       */
      /**
       * The surface is the one part that emits a `dir` nobody asked for,
       * and the portal is the whole reason. The adapter mounts it into
       * `document.body` (react/src/portal.tsx), outside whatever RTL region the
       * trigger sits in, and inheritance does not cross a portal — so the
       * direction has to be carried over explicitly. What was removed everywhere is the
       * ltr DEFAULT, not the attribute: a part still emits `dir` when the consumer
       * passes one. The default was the bug — emitting a direction nobody asked
       * for *overrode* the inheritance that already worked.
       *
       * Read from the anchor, never from the surface: the surface is in the body
       * and would only report the document's own direction back to itself. And in
       * an effect rather than in `connect`, so the server emits nothing and the
       * first client render has nothing to disagree with.
       */
      trackSurfaceDir({ prop, context, scope }) {
        context.set("surfaceDir", resolveDir(prop("dir"), getDirAnchorEl(scope)));
      },

      trackAnchorPosition({ prop, computed, refs, scope, send }) {
        const positioner = getPositionerEl(scope);
        if (positioner === null) return;

        if (computed("presentation") !== "popup") {
          for (const name of POSITION_STYLES) positioner.style.removeProperty(name);
          positioner.style.removeProperty("--sui-transform-origin");
          return;
        }

        // A right click anchors to the point, not to the region: a zero-sized rect
        // where the pointer landed is exactly what `computePosition` wants.
        const point = refs.get("anchorPoint");
        const getAnchorRect =
          prop("getAnchorRect") ??
          (point === null
            ? undefined
            : (): Rect => {
                const current = refs.get("anchorPoint");
                return current === null
                  ? ZERO_RECT
                  : { x: current.x, y: current.y, width: 0, height: 0 };
              });

        return trackPosition(getAnchorEl(scope), positioner, {
          placement: computed("placement"),
          ...(computed("isSubmenu") ? { fallbackPlacements: SUBMENU_FALLBACKS } : {}),
          gap: prop("gap"),
          offset: prop("offset"),
          flip: prop("flip"),
          shift: prop("shift"),
          padding: prop("padding"),
          matchWidth: prop("matchWidth"),
          // From the anchor, not from the surface: the surface is portalled into
          // `document.body` and would report the document's direction, while the
          // side a submenu opens on is decided by the region the trigger sits in.
          dir: resolveDir(prop("dir"), getDirAnchorEl(scope)),
          strategy: prop("strategy"),
          boundary: prop("boundary"),
          getAnchorRect,
          onPositioned: (result) => send({ type: "POSITION.SYNC", placement: result.placement }),
        });
      },

      /**
       * The surface takes the focus so the keys reach it; `highlightInitial` moves
       * it onto an item straight after, from the open state's entry.
       *
       * The disposer is the restore, and it only fires when the focus is still
       * inside: a person who left by clicking elsewhere, or by tabbing past the
       * trigger, has already said where they want to be. A trigger disabled while
       * open takes nothing, so `restoreFocus` falls back on its neighbour (R61).
       */
      focusContent({ prop, refs, scope }) {
        const content = getContentEl(scope);
        if (content === null) return;
        if (prop("autoFocus")) focusElement(prop("initialFocus")?.() ?? content);
        return () => {
          if (!prop("restoreFocus")) return;
          if (!contains(content, scope.getActiveElement())) return;
          const target = prop("finalFocus")?.() ?? refs.get("finalFocusEl") ?? getAnchorEl(scope);
          restoreFocus(target, content);
        };
      },

      /**
       * Tab closes the whole tree (APG Menu Button); this places the step past the
       * root's anchor, for the focus in any open submenu too.
       *
       * Modal: the trigger is inert until `hideOutside` releases it, which the
       * reverse teardown does before this disposer, so the step is held until
       * then — and only when the menu is really closing: a refused close and a
       * `reenter` keep it open, and the focus stays inside.
       */
      proxyTabs({ context, scope }) {
        return proxyTabFocus(getContentEl(scope), {
          triggerNode: () => getAnchorEl(scope),
          placeOnDispose: () => !context.get("open"),
        });
      },

      hideOutside({ prop, scope }) {
        if (!prop("modal")) return;
        return hideOthers(
          [
            getContentEl(scope),
            getPositionerEl(scope),
            getBackdropEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          { inert: true },
        );
      },

      /**
       * **Not `trapped`:** a trapped scope answers `consumed` for everything it
       * declines and silences every non-`base` scope under it outside its surface,
       * whether or not the menu is modal. The spatial engine is a `base` scope and
       * is asked either way, so trapping buys no confinement: that is declared
       * where it belongs, `data-snav-trap` on the content when the menu is modal.
       *
       * `contextMenu` (Y) is deliberately *not* claimed: Y is what opens a context
       * menu on the focused element, so a menu that swallowed it would make the
       * one gesture it exists for impossible from inside itself.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        const content = getContentEl(scope);
        if (host === null || host === undefined || content === null) return;
        const id = getContentId(scope);
        const stack = getLayerStack(content.ownerDocument);

        return host.pushScope((event) => {
          if (event.intent === "back") {
            if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
            // Through the layer — the top one, checked above — which counts it: see
            // `LayerStack.dismissals`. Under a `NavProvider` Escape arrives here as
            // `back` too, so a held Tab is dropped for both only on this road.
            stack.dismissTop("back");
            return true;
          }
          // Everything else is about the highlight, and the highlight is this
          // menu's only when the real focus is in it — a parent and its open child
          // both hold a scope.
          if (!ownsFocus(scope)) return false;

          if (event.intent === "select") {
            send({ type: "ITEM.ACTIVATE" });
            return true;
          }

          const intentDir = resolveDir(prop("dir"), content);

          const submenu = getSubmenuIntentAction(event.intent, intentDir);
          if (submenu !== null) {
            send(
              submenu === "open" ? { type: "CHILD.OPEN", focus: true } : { type: "CHILD.CLOSE" },
            );
            return true;
          }

          const key = toRovingIntentKey(event.intent);
          if (key === null) return false;
          const action = getRovingKeyAction(key, {
            orientation: "vertical",
            dir: intentDir,
          });
          if (action === null) return false;
          send({ type: "HIGHLIGHT.MOVE", action });
          return true;
        });
      },

      /**
       * Owns the submenu timer and the pointer trail, and hands both back: a menu
       * that closed while a submenu was about to open would otherwise fire into a
       * service that has already stopped.
       */
      trackPointerIntent(params) {
        return () => {
          cancelIntent(params);
          params.refs.set("pointerTrail", []);
        };
      },

      /** See `flashSelection` — this effect exists for its disposer. */
      trackSelectionFlash({ refs, context }) {
        return () => {
          refs.get("flashTimer")?.();
          refs.set("flashTimer", null);
          context.set("flashingValue", null);
        };
      },

      trackParts({ prop, scope, send }) {
        send({ type: "PARTS.SYNC" });
        const content = getContentEl(scope);
        const cancel = getCancelTriggerEl(scope);
        warn(
          isDev() && cancel !== null && !hasAccessibleName(cancel),
          "a menu cancel trigger has no accessible name — give it text, `aria-label` or `title`",
        );
        // The surface names itself after its trigger, and a context menu has none.
        // `aria-labelledby` is withheld in that case rather than left dangling, so
        // without a `label` the menu ends up unnamed — which is worth saying out
        // loud, because the alternative is an IDREF that resolves to nothing and
        // that axe only ever reports as `incomplete`.
        warn(
          isDev() && prop("label") === undefined && getTriggerEl(scope) === null,
          "a menu with no trigger has no accessible name — pass `label`, or render a trigger",
        );
        return observeChildren(content, () => send({ type: "PARTS.SYNC" }));
      },

      /**
       * WCAG 2.2 §1.4.13 has nothing to say here, but the CDC parity list does:
       * a menu that caps itself against the viewport is the one surface in this
       * library whose content can be cut off with no scrollbar to say so — desktop
       * overlay scrollbars hide until the pointer moves, and a finger gets none at
       * all. So the surface says it itself, and the sheet draws the edge.
       *
       * No `prefers-reduced-motion` guard, and that is the point: this is not an
       * animation, it is the only indication that there is more menu. Reduced
       * motion softens how a thing arrives; it never deletes what the thing says.
       */
      trackScrollEdges({ scope }) {
        return trackEdges(getContentEl(scope));
      },
    },
  },
});

import type { RovingAction } from "../../focus/roving-focus";
import type { DismissReason } from "../../interaction/layer-stack";
import type { TypeaheadState } from "../../interaction/typeahead";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema, Service } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Placement } from "../../positioner/compute-position";
import type { Density, Direction, InputModality, Rect } from "../../types";

/** What the surface actually is once the density has had its say. */
export type MenuPresentation = "popup" | "sheet";

export type MenuPresentationProp = "auto" | MenuPresentation;

/** The three roles an item can carry. The value state itself is never the menu's. */
export type MenuOptionType = "checkbox" | "radio";

export interface MenuPoint {
  readonly x: number;
  readonly y: number;
}

export interface MenuOpenChangeDetails {
  readonly open: boolean;
}

export interface MenuSelectDetails {
  readonly value: string;
}

export interface MenuHighlightChangeDetails {
  readonly value: string | null;
}

export interface MenuDismissDetails {
  readonly reason: DismissReason;
}

export interface MenuMachineProps {
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  readonly presentation?: MenuPresentationProp | undefined;

  // --- positioning, handed straight to the positioner ------------------------
  /**
   * Left undefined on purpose. A root menu falls back to `bottom-start` and a
   * submenu to `right-start`, and which of the two applies is only known once the
   * parent has been wired — so the resolution is a `computed`, not a default.
   */
  readonly placement?: Placement | undefined;
  readonly gap?: number | undefined;
  readonly offset?: number | undefined;
  readonly flip?: boolean | undefined;
  readonly shift?: boolean | undefined;
  readonly padding?: number | undefined;
  readonly matchWidth?: boolean | undefined;
  readonly strategy?: "absolute" | "fixed" | undefined;
  readonly boundary?: (() => Rect) | undefined;
  /** Anchor to a rect rather than an element — a caret, a canvas, a pointer. */
  readonly getAnchorRect?: (() => Rect) | undefined;

  // --- collection ------------------------------------------------------------
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly loopFocus?: boolean | undefined;
  readonly typeahead?: boolean | undefined;
  /** Overridable per item through `getItemProps({ closeOnSelect })`. */
  readonly closeOnSelect?: boolean | undefined;
  readonly highlightedValue?: string | null | undefined;
  readonly defaultHighlightedValue?: string | null | undefined;

  // --- dismissal -------------------------------------------------------------
  readonly closeOnEscape?: boolean | undefined;
  readonly closeOnInteractOutside?: boolean | undefined;
  /**
   * The native behaviour, and the one the reference app's own context menu had (parity M5):
   * the click that closes a menu must not also activate whatever was under it.
   */
  readonly preventOutsideActivation?: boolean | undefined;
  /**
   * `false`, and that is a decision rather than an omission. `layer-stack`
   * documents `modal` as "inert plus scroll lock" — the dialog's contract, and
   * disproportionate for a menu. Confinement comes from the dismissable layer and
   * the intent stack instead.
   */
  readonly modal?: boolean | undefined;
  /** Defaults to the `sheet` presentation and is ignored in `popup`. */
  readonly preventScroll?: boolean | undefined;

  // --- focus -----------------------------------------------------------------
  readonly autoFocus?: boolean | undefined;
  readonly restoreFocus?: boolean | undefined;
  readonly initialFocus?: (() => HTMLElement | null) | undefined;
  readonly finalFocus?: (() => HTMLElement | null) | undefined;

  // --- submenus and motion ---------------------------------------------------
  readonly submenuOpenDelay?: number | undefined;
  readonly submenuCloseDelay?: number | undefined;
  /** The selection blink. Off in `sheet` and under reduced motion, whatever is asked. */
  readonly selectionFlash?: boolean | undefined;

  readonly disabled?: boolean | undefined;
  readonly persistentElements?: (() => readonly HTMLElement[]) | undefined;
  readonly parentId?: string | undefined;
  /** The accessible name when the surface has no trigger to be labelled by. */
  readonly label?: string | undefined;
  readonly intents?: IntentScopeHost | null | undefined;

  readonly onOpenChange?: ((details: MenuOpenChangeDetails) => void) | undefined;
  readonly onSelect?: ((details: MenuSelectDetails) => void) | undefined;
  readonly onHighlightChange?: ((details: MenuHighlightChangeDetails) => void) | undefined;
  readonly onDismiss?: ((details: MenuDismissDetails) => void) | undefined;
}

export interface ResolvedMenuMachineProps extends MenuMachineProps {
  readonly defaultOpen: boolean;
  readonly presentation: MenuPresentationProp;
  readonly gap: number;
  readonly offset: number;
  readonly flip: boolean;
  readonly shift: boolean;
  readonly padding: number;
  readonly matchWidth: boolean;
  readonly strategy: "absolute" | "fixed";
  readonly loopFocus: boolean;
  readonly typeahead: boolean;
  readonly closeOnSelect: boolean;
  readonly closeOnEscape: boolean;
  readonly closeOnInteractOutside: boolean;
  readonly preventOutsideActivation: boolean;
  readonly modal: boolean;
  readonly autoFocus: boolean;
  readonly restoreFocus: boolean;
  readonly submenuOpenDelay: number;
  readonly submenuCloseDelay: number;
  readonly selectionFlash: boolean;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface MenuSchema extends MachineSchema {
  state: "open" | "closed";
  props: ResolvedMenuMachineProps;
  context: {
    /** The single source of truth; the state is a projection of it. */
    open: boolean;
    density: Density;
    /**
     * The direction the portalled surface is drawn in, resolved from the anchor
     * when it opens. `null` until then — and on the server — which is what keeps
     * the first client render agreeing with the markup it hydrates.
     */
    surfaceDir: Direction | null;
    /** Where the surface landed — the preferred placement may have flipped. */
    currentPlacement: Placement;
    highlightedValue: string | null;
    /** Whether the checkmark gutter is reserved, derived from the rendered parts. */
    hasSelectionGutter: boolean;
    /** Whether any row draws a glyph, and so whether the symbol track is reserved for all of them. */
    hasSymbolGutter: boolean;
    /**
     * Whether a `trigger` part is really rendered. Read from the DOM alongside the
     * gutter, and for the same reason `connect` cannot ask: a menu composed only
     * with `getContextTriggerProps` has no trigger at all, and naming its surface
     * after one leaves `aria-labelledby` pointing at an id nobody ever wrote.
     */
    hasTrigger: boolean;
    hasParent: boolean;
    /** The item mid-blink; the close is deferred until it ends. */
    flashingValue: string | null;
    /**
     * The modality the highlight arrived under, held until it moves again. Not a
     * copy of `data-snav-input`, which is the modality of *now* and flips to
     * `pointer` after 300 ms of mouse movement whether the focus moved or not.
     */
    focusSource: InputModality | null;
  };
  computed: {
    presentation: MenuPresentation;
    isSubmenu: boolean;
    /** `bottom-start` at the root, `right-start` once a parent is wired. */
    placement: Placement;
  };
  refs: {
    finalFocusEl: HTMLElement | null;
    /** Where a right click or a long press landed — the context-menu anchor. */
    anchorPoint: MenuPoint | null;
    parent: Service<MenuSchema> | null;
    child: Service<MenuSchema> | null;
    typeahead: TypeaheadState;
    /** Owned by `trackPointerIntent`; the submenu open/close delay lives on it. */
    intentTimer: VoidFunction | null;
    /** Owned by `trackSelectionFlash`; cancelled the moment the surface leaves. */
    flashTimer: VoidFunction | null;
    /** The last few pointer positions — the safe triangle reads this. */
    pointerTrail: readonly MenuPoint[];
    /** Press-drag-release: the click that follows the opening press is not a toggle. */
    openedAt: number;
    /**
     * Where the highlight goes the moment the surface exists. The keyboard asks
     * for it *before* the content is mounted, so the request has to outlive the
     * event that made it.
     */
    pendingHighlight: RovingAction | null;
  };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "TRIGGER.POINTERDOWN" }
    | { type: "TRIGGER.KEYDOWN"; action: RovingAction }
    | { type: "TRIGGER.CONTEXTMENU"; x: number; y: number }
    | { type: "TRIGGER.LONGPRESS"; x: number; y: number }
    | { type: "ITEM.POINTERMOVE"; value: string; x: number; y: number }
    | { type: "ITEM.POINTERLEAVE"; value: string }
    | { type: "ITEM.CLICK"; value: string; closeOnSelect?: boolean | undefined }
    | { type: "ITEM.SELECT"; value: string; closeOnSelect?: boolean | undefined }
    | { type: "ITEM.ACTIVATE" }
    | { type: "HIGHLIGHT.MOVE"; action: RovingAction }
    /** `null` clears it — there is no second event for that. */
    | { type: "HIGHLIGHT.SET"; value: string | null }
    | { type: "TYPEAHEAD.KEY"; key: string }
    | { type: "FLASH.END" }
    /**
     * `value` names the trigger item the request is *about*. A click carries it,
     * because a synthetic or touch activation reaches the item with no
     * `pointermove` before it and therefore no highlight to read. Left out — the
     * arrow key, the d-pad, the hover timer — the highlight is the subject, which
     * is what makes the request refusable when it sits on a plain item.
     */
    | { type: "CHILD.OPEN"; focus?: boolean | undefined; value?: string | undefined }
    | { type: "CHILD.CLOSE" }
    | { type: "CHILD.SET"; child: Service<MenuSchema> | null }
    | { type: "PARENT.SET"; parent: Service<MenuSchema> | null }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "TREE.CLOSE" }
    | { type: "CANCEL.CLICK" }
    | { type: "POSITION.SYNC"; placement: Placement }
    | { type: "OPEN.SET"; open: boolean; highlight?: RovingAction | undefined }
    | { type: "OPEN.SYNC" }
    | { type: "PRESENTATION.SYNC" }
    | { type: "ENVIRONMENT.SYNC"; density: Density }
    | { type: "PARTS.SYNC" };
  action:
    | "toggleMenu"
    | "openMenu"
    | "closeMenu"
    | "closeTree"
    | "setOpen"
    | "setAnchorPoint"
    | "captureFinalFocus"
    | "highlightInitial"
    | "highlightItem"
    | "moveHighlight"
    | "focusHighlighted"
    | "typeaheadHighlight"
    | "recordPointer"
    | "scheduleChild"
    | "scheduleChildClose"
    | "activateHighlighted"
    | "invokeOnSelect"
    | "flashSelection"
    | "clearFlash"
    | "openChild"
    | "closeChild"
    | "closeStaleChild"
    | "setChild"
    | "setParent"
    | "invokeOnDismiss"
    | "syncEnvironment"
    | "syncPlacement"
    | "syncParts";
  guard:
    | "isEnabled"
    | "isOpen"
    | "isSubmenu"
    | "canDismiss"
    | "isItemEnabled"
    | "isTriggerItem"
    | "isPointerHeadingToChild"
    | "hasOpenChild"
    | "hasChildFor"
    | "shouldCloseOnSelect"
    | "shouldFlash"
    | "isTypeaheadEnabled";
  effect:
    | "trackEnvironment"
    | "trackModality"
    | "trackSurfaceDir"
    | "trackContextTrigger"
    | "trackDismissable"
    | "lockPageScroll"
    | "trackAnchorPosition"
    | "focusContent"
    | "proxyTabs"
    | "hideOutside"
    | "captureIntents"
    | "trackPointerIntent"
    | "trackSelectionFlash"
    | "trackParts"
    | "trackScrollEdges";
}

// --- prop-getter inputs ------------------------------------------------------

export interface MenuItemProps {
  readonly value: string;
  readonly disabled?: boolean | undefined;
  /** A destructive action. First class on both densities. */
  readonly destructive?: boolean | undefined;
  /** Typeahead text and `data-label`; falls back to the `itemText` part. */
  readonly label?: string | undefined;
  /** Overrides the machine's `closeOnSelect` for this item alone. */
  readonly closeOnSelect?: boolean | undefined;
  /** Announced through `aria-keyshortcuts`; the `itemShortcut` part is decoration. */
  readonly shortcut?: string | undefined;
  /** The item renders an `itemDescription` part — wires `aria-describedby`. */
  readonly description?: boolean | undefined;
}

/**
 * Controlled by the consumer, and deliberately so — a divergence from
 * `radio-group` and `checkbox-group`, which do hold bindables. A menu is a
 * transient surface that unmounts; the checked state belongs to the app's model,
 * not to an overlay, and keeping it out is also what keeps the budget.
 */
export interface MenuOptionItemProps extends MenuItemProps {
  readonly type: MenuOptionType;
  readonly checked?: boolean | undefined;
  readonly onCheckedChange?: ((checked: boolean) => void) | undefined;
}

export interface MenuItemGroupProps {
  /** Ties the group to its label. Any stable string the consumer owns. */
  readonly id: string;
  /**
   * The group renders an `itemGroupLabel` part — wires `aria-labelledby`. Same
   * shape as `MenuItemProps.description` and declared for the same reason:
   * `connect` is pure, so it cannot look for the label. Written unconditionally
   * the attribute is worse than absent — the group ends with no accessible name
   * *and* a dangling IDREF, which axe reports as `incomplete` rather than a
   * violation, so no test catches it.
   */
  readonly label?: boolean | undefined;
  readonly orientation?: "vertical" | "horizontal" | undefined;
}

export interface MenuItemGroupLabelProps {
  readonly htmlFor: string;
}

export interface MenuItemDescriptionProps {
  readonly value: string;
}

export interface MenuItemIndicatorProps {
  readonly checked?: boolean | undefined;
}

export interface MenuApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  readonly presentation: MenuPresentation;
  /** Where the surface landed, which is not necessarily what was asked for. */
  readonly placement: Placement;
  readonly highlightedValue: string | null;
  readonly isSubmenu: boolean;
  readonly triggerId: string;
  readonly contentId: string;

  setOpen(open: boolean): void;
  setHighlightedValue(value: string | null): void;
  /** Closes every level, root included — what Tab and the cancel button do. */
  closeTree(): void;
  /** Call from an adapter **effect**, never during render: it sends an event. */
  setParent(parent: Service<MenuSchema> | null): void;
  /** Call from an adapter **effect**, never during render: it sends an event. */
  setChild(child: Service<MenuSchema> | null): void;

  getTriggerProps(): T["button"];
  getContextTriggerProps(): T["element"];
  getIndicatorProps(): T["element"];
  getBackdropProps(): T["element"];
  getPositionerProps(): T["element"];
  getContentProps(): T["element"];
  getItemGroupProps(props: MenuItemGroupProps): T["element"];
  getItemGroupLabelProps(props: MenuItemGroupLabelProps): T["element"];
  getItemProps(props: MenuItemProps): T["element"];
  getOptionItemProps(props: MenuOptionItemProps): T["element"];
  /** The parent's item props and the child's trigger props, on one node. */
  getTriggerItemProps(child: MenuApi<T>, props: MenuItemProps): T["element"];
  getItemSymbolProps(): T["element"];
  getItemTextProps(): T["element"];
  getItemDescriptionProps(props: MenuItemDescriptionProps): T["element"];
  getItemIndicatorProps(props: MenuItemIndicatorProps): T["element"];
  getItemShortcutProps(): T["element"];
  getSeparatorProps(): T["element"];
  getCancelTriggerProps(): T["button"];
}

/**
 * `<Menu items={…}/>` — the deepest composed layer in the library, and the only
 * one with a recursive branch: a submenu is a `<MenuRoot>` nested inside its
 * parent's content whose first child is a `<MenuTriggerItem>`, which is the shape
 * the part imposes and documents, so the layer walks the tree the consumer hands
 * it and writes that shape at every level.
 *
 * **Nothing here holds the collection.** `menu.tsx` opens on the invariant — "the
 * items are composition, never an `items` prop; the machine reads the live DOM" —
 * and mapping an array into `<MenuItem>` elements before the render does not
 * contradict it: no registry, no memo, no state. Five call sites can still be five
 * different lists; four of them can now be four arrays. That is the reference app's
 * `ContextMenu`, which is one hand-written surface repeated five times with
 * neither typeahead nor submenus.
 *
 * Three translations that are a11y defects if they are skipped, and one that is
 * merely a shape:
 *
 *  - **A group's `label` is the text here and a boolean flag on the part.**
 *    Passing the string through would be truthy, so `aria-labelledby` would be
 *    written and point at a label part nobody rendered — a dead IDREF and a
 *    nameless group at once. `id` is required on a group so the two ends meet.
 *  - **A row's `description` is the text here and a boolean flag on the part**,
 *    for exactly the same reason: `getItemProps` writes `aria-describedby` only
 *    when `description === true`, at an id derived from the row's value, so the
 *    text and the flag have to arrive together or neither should.
 *  - **A row's `label` is required** where the part leaves it optional. It is the
 *    typeahead text, the `data-label` *and* the words `MenuItemText` shows, and
 *    the composed layer is the only place all three come from.
 *  - **The checkmark cell is placed on checkable rows alone.** The gutter is a
 *    decision of the *surface*: the machine reads whether any row owns an
 *    `item-indicator` and reserves the leading track for every row when one does.
 *    An indicator on a plain `menuitem` would open that column in menus that have
 *    nothing to check.
 *
 * `cancelLabel` travels to `MenuContent`, which already withholds the Cancel row
 * outside the `sheet` presentation — the façade passes it, it does not
 * reimplement it. Selection comes back through `onSelect` on the root, never a
 * handler per row: the machine has that event and inventing a second name for it
 * would be a closure per line and a second truth about what was chosen.
 */

import type {
  MenuItemProps as CoreMenuItemProps,
  MenuOptionItemProps as CoreMenuOptionItemProps,
} from "@standarui/core/menu";
import type { ReactNode } from "react";
import type {
  ComposedDecoration,
  ComposedGroup,
  ComposedSeparator,
  ComposedTrigger,
} from "../../composed";
import type { PartProps } from "../../create-part";
import type { PortalProps } from "../../portal";
import {
  MenuBackdrop,
  MenuContent,
  type MenuContentProps,
  MenuContextTrigger,
  MenuItem,
  MenuItemDescription,
  MenuItemGroup,
  MenuItemGroupLabel,
  type MenuItemGroupProps,
  MenuItemIndicator,
  MenuItemShortcut,
  MenuItemSymbol,
  MenuItemText,
  MenuOptionItem,
  MenuPortal,
  type MenuPortalProps,
  MenuPositioner,
  MenuRoot,
  MenuSeparator,
  MenuTrigger,
  MenuTriggerItem,
  type UseMenuProps,
} from "./menu";

/**
 * A plain row: the part's own props — an intersection, never a `Pick`, so a field
 * added to `MenuItemProps` shows up here without anyone thinking about it — plus
 * the two fields no machine owns, with `label` narrowed to required and
 * `description` from a flag to its text (see the header for both).
 *
 * `shortcut` is the part's own field and is spent twice on purpose: it reaches
 * assistive technology as `aria-keyshortcuts` on the row and it is drawn by
 * `MenuItemShortcut`, which is `aria-hidden`, so the same string can never be
 * announced twice. A consumer who needs the announced form to differ from the
 * drawn one writes the parts.
 */
export type MenuAction<V extends string = string, Meta = never> = Omit<
  CoreMenuItemProps,
  "value" | "label" | "description"
> &
  ComposedDecoration<Meta> & {
    readonly value: V;
    readonly label: string;
    /** The iOS subtitle. Text here, a boolean flag plus a part on the row. */
    readonly description?: string | undefined;
  };

/**
 * A checkable or radio row. The checked state stays the consumer's, exactly as it
 * does on the part: a menu is a transient surface, and the value belongs to the
 * model behind it rather than to an overlay that unmounts.
 */
export type MenuCheckable<V extends string = string, Meta = never> = Omit<
  CoreMenuOptionItemProps,
  "value" | "label" | "description"
> &
  ComposedDecoration<Meta> & {
    readonly value: V;
    readonly label: string;
    readonly description?: string | undefined;
  };

/** Every entry that ends up as a `menu:item` — the two the escape hatch reaches. */
export type MenuRow<V extends string = string, Meta = never> =
  | MenuAction<V, Meta>
  | MenuCheckable<V, Meta>;

/**
 * The one recursive branch in the library, and the depth is the consumer's data.
 * `items` rather than `options` so the narrowing stays a single `in` test against
 * a group.
 */
export interface MenuSubmenu<V extends string = string, Meta = never> {
  readonly value: V;
  readonly label: string;
  /**
   * The nested machine's scope id, and the one field a group's `id` and this one
   * do not share a reason for. A group needs it or its `aria-labelledby` dangles;
   * a submenu without it is correct — `useMachine` mints one from React's own id
   * hook, and the server and the client agree on it. What it buys is what a
   * group's key buys: every id under this surface becomes the consumer's rather
   * than React's, which is what a server render has to match to the character.
   */
  readonly id?: string | undefined;
  readonly disabled?: boolean | undefined;
  readonly icon?: ReactNode;
  readonly items: readonly MenuEntry<V, Meta>[];
}

/**
 * Narrowed structurally, in this order: `"separator" in e`, then `"options" in e`
 * (a group), then `"items" in e` (a submenu), then `"type" in e` (a checkable
 * row), else a plain row. No `kind` field anywhere, and the collection names
 * differ on purpose so each test is one `in`.
 */
export type MenuEntry<V extends string = string, Meta = never> =
  | MenuRow<V, Meta>
  | MenuSubmenu<V, Meta>
  | ComposedGroup<MenuEntry<V, Meta>>
  | ComposedSeparator;

/**
 * The escape hatch, applied **last** on every part: the layer's own defaults are
 * defaults, and the consumer's entry wins over them.
 *
 * Sixteen keys: the fifteen parts of `menu.anatomy.ts` this layer places, plus
 * `portal` — which is no part at all but the React container the parts form wraps
 * the surface in. Two of the anatomy's seventeen are absent, because this layer
 * never places them: `indicator` is the chevron on a trigger whose content is the
 * consumer's own element, and `cancelTrigger` is placed by `MenuContent` itself
 * out of `cancelLabel`, which is where it has to stay — the part withholds
 * itself outside the `sheet` presentation and only the part knows that.
 */
export interface MenuParts {
  readonly trigger?: PartProps<"button"> | undefined;
  readonly contextTrigger?: PartProps<"div"> | undefined;
  /** Reaches every surface in the tree, the root's and each submenu's. */
  readonly portal?: MenuPortalProps | undefined;
  readonly backdrop?: PartProps<"div"> | undefined;
  readonly positioner?: PartProps<"div"> | undefined;
  readonly content?: MenuContentProps | undefined;
  /** Applied to EVERY group — `id` and `label` are the entry's, one per group. */
  readonly itemGroup?: Omit<MenuItemGroupProps, "id" | "label"> | undefined;
  readonly itemGroupLabel?: PartProps<"div"> | undefined;
  /**
   * Applied to EVERY row, hence no `id` **and no IDREF**: one id repeated down a
   * menu is a broken reference per row, and one `aria-labelledby` repeated gives
   * every row the same name — which no dangling-IDREF check can see, because the
   * id it points at does resolve. `ref` goes for the same reason: a single ref
   * held by N rows ends up holding the last one.
   */
  readonly item?:
    | Omit<
        PartProps<"div">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  /** Applied to EVERY submenu row, and repeated for the same reasons. */
  readonly triggerItem?:
    | Omit<
        PartProps<"div">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly itemSymbol?:
    | Omit<
        PartProps<"span">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly itemText?:
    | Omit<
        PartProps<"span">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly itemDescription?:
    | Omit<
        PartProps<"span">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly itemIndicator?:
    | Omit<
        PartProps<"span">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly itemShortcut?:
    | Omit<
        PartProps<"kbd">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  readonly separator?: PartProps<"div"> | undefined;
}

export interface MenuComposedProps<V extends string = string, Meta = never> extends UseMenuProps {
  readonly items: readonly MenuEntry<V, Meta>[];
  /**
   * Handed to `MenuTrigger` as `render` — never as its children. The trigger *is*
   * a `<button>`, and a button inside a button is `nested-interactive`. Exactly
   * one of `trigger` and `contextTrigger`; the function's own signature refuses
   * both at once.
   */
  readonly trigger?: ComposedTrigger | undefined;
  /**
   * The region a right click, a long press, Shift+F10, the ≣ key or the pad's
   * `contextMenu` intent opens the surface from. Children rather than `render`,
   * because `MenuContextTrigger` is a plain container with no handler of its own
   * — the listeners are installed natively by the machine, since they have to be
   * listening while the surface is closed.
   *
   * A surface with neither anchor is legal and is the store-driven shape:
   * `open` on one side, `label` for the name the trigger would have given it.
   */
  readonly contextTrigger?: ReactNode;
  /**
   * The action sheet's Cancel row, handed straight to `MenuContent`, which
   * renders it in the `sheet` presentation and nowhere else. The library ships no
   * copy of its own; `null` is read as absent for the reason the part reads
   * `undefined` that way — `getCancelTriggerProps` writes no accessible name, so
   * an empty button would be a nameless one.
   */
  readonly cancelLabel?: ReactNode;
  /** Reaches every portal in the tree, so a submenu cannot escape its parent's host. */
  readonly container?: PortalProps["container"] | undefined;
  /** Keeps every surface in the tree mounted while closed; the sheet hides them. */
  readonly keepMounted?: boolean | undefined;
  /**
   * Replaces the CHILDREN of a row, never the row. `defaults` is what the layer
   * would have rendered — the checkmark cell on a checkable, the symbol, the
   * text, the subtitle, the shortcut — and it is handed over so that
   * **decorating** is the cheapest thing to do, not because replacing is
   * impossible. Rendering something else instead of `defaults` is the consumer's
   * to do and costs them the part that names the row (`MenuItemText`), the
   * checkmark, and the leading column those two share.
   *
   * Decorate as a **sibling** of `defaults`, never by wrapping it in an element:
   * a row's children are its grid cells (`_menu.scss`, `grid-template-columns` on
   * `menu:item`), each one placed by `grid-column`, so a wrapper takes all of
   * them out of the grid at once.
   *
   * Rows only. A group is not one, a separator is not one, and a submenu's
   * trigger item is not one either — it opens a surface rather than choosing, and
   * the sheet draws its chevron as a pseudo-element on the row itself.
   */
  readonly renderItem?: ((item: MenuRow<V, Meta>, defaults: ReactNode) => ReactNode) | undefined;
  readonly parts?: MenuParts | undefined;
}

/**
 * What every level of the tree needs and nothing else. Passed down rather than
 * closed over so the recursion stays a plain function: the module runs no hook,
 * which is what `scripts/composed-grammar.test.ts` reads it for.
 */
interface MenuTree<V extends string, Meta> {
  readonly parts: MenuParts | undefined;
  readonly container: PortalProps["container"] | undefined;
  readonly keepMounted: boolean | undefined;
  readonly render: ((item: MenuRow<V, Meta>, defaults: ReactNode) => ReactNode) | undefined;
  readonly inherited: MenuInherited;
}

/**
 * What every surface of the tree answers to, and the reason the recursion carries
 * it: each `MenuSubmenu` is its own machine, and `invokeOnSelect` reads the
 * `onSelect` of the machine that received the event. A nested root given only its
 * `id` therefore closed the tree and told the consumer nothing — `<Menu onSelect>`
 * never fired for a row chosen in a submenu, in flat contradiction of the promise
 * at the top of this module (audit of 2026-09-05).
 *
 * These are the props that describe how a menu *surface* behaves. What stays on
 * the root alone is what belongs to one surface: its `id`, its open state and the
 * callbacks around it, its focus props, `modal` and `preventScroll` (a submenu
 * inside a modal tree is already inside that layer; a second lock is not the same
 * request), and `preventOutsideActivation`, which the tree's outermost layer owns.
 */
type MenuInherited = Pick<
  UseMenuProps,
  | "onSelect"
  | "onHighlightChange"
  | "closeOnSelect"
  | "typeahead"
  | "loopFocus"
  | "submenuOpenDelay"
  | "submenuCloseDelay"
  | "selectionFlash"
>;

/**
 * One row. `icon` and `meta` are lifted out because the rest of the entry is
 * spread straight onto the part: `icon` belongs to a part of its own and `meta`
 * belongs to the consumer, and neither is an attribute of a `<div>`. `description`
 * is lifted for the third reason in the header — the part takes the flag, the
 * subtitle part takes the words.
 */
function renderRow<V extends string, Meta>(
  row: MenuRow<V, Meta>,
  tree: MenuTree<V, Meta>,
): ReactNode {
  const { parts, render } = tree;
  const defaults = (
    <>
      {"type" in row ? <MenuItemIndicator {...parts?.itemIndicator} /> : null}
      {row.icon === undefined ? null : (
        <MenuItemSymbol {...parts?.itemSymbol}>{row.icon}</MenuItemSymbol>
      )}
      <MenuItemText {...parts?.itemText}>{row.label}</MenuItemText>
      {row.description === undefined ? null : (
        <MenuItemDescription {...parts?.itemDescription}>{row.description}</MenuItemDescription>
      )}
      {row.shortcut === undefined ? null : (
        <MenuItemShortcut {...parts?.itemShortcut}>{row.shortcut}</MenuItemShortcut>
      )}
    </>
  );
  const children = render === undefined ? defaults : render(row, defaults);

  if ("type" in row) {
    const { icon, meta, description, ...item } = row;
    return (
      <MenuOptionItem
        key={row.value}
        {...item}
        description={description !== undefined}
        {...parts?.item}
      >
        {children}
      </MenuOptionItem>
    );
  }

  const { icon, meta, description, ...item } = row;
  return (
    <MenuItem key={row.value} {...item} description={description !== undefined} {...parts?.item}>
      {children}
    </MenuItem>
  );
}

/**
 * A submenu, written the way the part imposes: a nested `<MenuRoot>` whose first
 * child is the `<MenuTriggerItem>`, which is what puts both apis on one node —
 * the parent's item props and this menu's own trigger props, under one part
 * token. The surface below it is the root's own tree again, which is the whole
 * recursion.
 */
function renderSubmenu<V extends string, Meta>(
  entry: MenuSubmenu<V, Meta>,
  tree: MenuTree<V, Meta>,
): ReactNode {
  const { parts, container, keepMounted, inherited } = tree;

  return (
    <MenuRoot key={entry.value} id={entry.id} keepMounted={keepMounted} {...inherited}>
      <MenuTriggerItem
        value={entry.value}
        label={entry.label}
        disabled={entry.disabled}
        {...parts?.triggerItem}
      >
        {entry.icon === undefined ? null : (
          <MenuItemSymbol {...parts?.itemSymbol}>{entry.icon}</MenuItemSymbol>
        )}
        <MenuItemText {...parts?.itemText}>{entry.label}</MenuItemText>
      </MenuTriggerItem>
      <MenuPortal container={container} {...parts?.portal}>
        <MenuBackdrop {...parts?.backdrop} />
        <MenuPositioner {...parts?.positioner}>
          <MenuContent {...parts?.content}>
            {entry.items.map((child, at) => renderEntry(child, at, tree))}
          </MenuContent>
        </MenuPositioner>
      </MenuPortal>
    </MenuRoot>
  );
}

function renderEntry<V extends string, Meta>(
  entry: MenuEntry<V, Meta>,
  index: number,
  tree: MenuTree<V, Meta>,
): ReactNode {
  const { parts } = tree;

  // A separator is not focusable, holds no state and has no subtree to unmount,
  // where an index on a row would move the focus mid-interaction — the collection
  // being the live DOM the machine reads.
  if ("separator" in entry) {
    return <MenuSeparator key={`sep:${index}`} {...parts?.separator} />;
  }
  if ("options" in entry) {
    return (
      <MenuItemGroup key={entry.id} id={entry.id} label {...parts?.itemGroup}>
        <MenuItemGroupLabel {...parts?.itemGroupLabel}>{entry.label}</MenuItemGroupLabel>
        {entry.options.map((child, at) => renderEntry(child, at, tree))}
      </MenuItemGroup>
    );
  }
  if ("items" in entry) return renderSubmenu(entry, tree);
  return renderRow(entry, tree);
}

export function Menu<V extends string = string, Meta = never>(
  props: MenuComposedProps<V, Meta> &
    ({ readonly contextTrigger?: undefined } | { readonly trigger?: undefined }),
): ReactNode {
  const {
    items,
    trigger,
    contextTrigger,
    cancelLabel,
    container,
    keepMounted,
    renderItem,
    parts,
    onSelect,
    onHighlightChange,
    closeOnSelect,
    typeahead,
    loopFocus,
    submenuOpenDelay,
    submenuCloseDelay,
    selectionFlash,
    ...root
  }: MenuComposedProps<V, Meta> = props;
  const inherited: MenuInherited = {
    onSelect,
    onHighlightChange,
    closeOnSelect,
    typeahead,
    loopFocus,
    submenuOpenDelay,
    submenuCloseDelay,
    selectionFlash,
  };
  const tree: MenuTree<V, Meta> = {
    parts,
    container,
    keepMounted,
    render: renderItem,
    inherited,
  };

  return (
    <MenuRoot {...root} {...inherited} keepMounted={keepMounted}>
      {trigger === undefined ? null : <MenuTrigger render={trigger} {...parts?.trigger} />}
      {contextTrigger == null ? null : (
        <MenuContextTrigger {...parts?.contextTrigger}>{contextTrigger}</MenuContextTrigger>
      )}
      <MenuPortal container={container} {...parts?.portal}>
        <MenuBackdrop {...parts?.backdrop} />
        <MenuPositioner {...parts?.positioner}>
          <MenuContent cancelLabel={cancelLabel ?? undefined} {...parts?.content}>
            {items.map((entry, index) => renderEntry(entry, index, tree))}
          </MenuContent>
        </MenuPositioner>
      </MenuPortal>
    </MenuRoot>
  );
}

/**
 * The menu in React: the popover's shape — a root that renders no element, a
 * portalled surface, two presences — plus the two things no overlay before it had.
 *
 * **A collection.** The items are composition, never a `items` prop (parity M1):
 * five call sites, five different lists. Nothing here holds them; the machine reads
 * the live DOM, and an item only has to publish its own value to its own parts.
 *
 * **A tree.** A submenu is a `<MenuRoot>` nested inside its parent's content, and
 * the two services have to know each other — the parent to aim, open and close its
 * child, the child to walk back up on `TREE.CLOSE`. The core makes that wiring two
 * events and says where it belongs ("call from an adapter effect, never during
 * render"), so it lives here, in `useMenuTree` and `claimChild`.
 *
 * Both hooks are keyed on **services**, never on apis: an api object is rebuilt on
 * every render, but every method on it sends into a service whose identity never
 * changes — so an api captured by an effect stays as good as the day it was made.
 */

import { type AnyProps, invariant, mergeProps, type Service } from "@standarui/core";
import * as menu from "@standarui/core/menu";
import { type ReactNode, type Ref, useId, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { LayerProvider, useParentLayerId } from "../../layer-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { Portal, type PortalProps } from "../../portal";
import { type PresenceApi, usePresence } from "../../presence";
import { splitProps } from "../../split-props";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";
import { useSafeLayoutEffect } from "../../use-safe-layout-effect";

export type MenuApi = menu.MenuApi<ReactPropTypes>;

export interface UseMenuProps extends menu.MenuMachineProps, MachineRuntimeProps {}

interface MenuContextValue {
  readonly api: MenuApi;
  readonly service: Service<menu.MenuSchema>;
  /**
   * The menu this one drills out of, and the adapter's only truth about being a
   * submenu. The machine's `isSubmenu` cannot be it: `parentId` also carries the
   * layer a menu was opened *from*, and a dialog is not a parent menu.
   */
  readonly parent: MenuContextValue | null;
  readonly keepMounted: boolean;
  readonly backdrop: PresenceApi;
  readonly content: PresenceApi;
}

/** An item publishes its identity so its parts do not have to repeat it. */
interface MenuItemContextValue {
  readonly value: string;
  readonly checked: boolean | undefined;
}

const MenuContext = createPartContext<MenuContextValue>("Menu");
const MenuItemContext = createPartContext<MenuItemContextValue>("Menu");
const MenuGroupContext = createPartContext<string>("Menu");

function useMenuService(
  props: UseMenuProps,
  parent: MenuContextValue | null,
): Service<menu.MenuSchema> {
  const parentLayerId = useParentLayerId();
  const host = useIntentScopeHost();

  return useMachine(menu.machine, {
    ...props,
    // `??` would override an explicit `null`, which is how a consumer says "this
    // surface answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
    parentId: props.parentId ?? parentLayerId,
    // A menu opened from inside another surface carries that surface's layer id so
    // the dismissable stack chains — but being inside a dialog does not make it a
    // submenu, and the machine's placement fallback has only `parentId` to go on.
    // React knows better: a submenu is a menu nested in another *menu's* context,
    // so the root case states its half of the fallback rather than inheriting
    // `right-start` from a layer that happens to exist.
    placement: props.placement ?? (parent === null ? "bottom-start" : undefined),
  });
}

/**
 * The machine on its own, for a consumer who would rather write the markup than
 * compose the parts. Nested inside another menu it wires itself up like `MenuRoot`
 * does — the parent is read from the same context either way.
 */
export function useMenu(props: UseMenuProps): MenuApi {
  const parent = MenuContext.useOptional();
  const service = useMenuService(props, parent);
  const api = menu.connect(service, normalizeProps);
  useMenuTree(api, service, parent);
  return api;
}

export function useMenuContext(): MenuApi {
  return MenuContext.usePart("MenuContext").api;
}

/**
 * The two links between a submenu and its parent. In an effect because both are
 * events: sending one while React renders would run somebody else's transition
 * mid-pass.
 *
 * Only the parent's half is undone. By the time this cleanup runs, this service is
 * already stopped — `useMachine` registered its own cleanup first — so telling it
 * to forget a parent would be an event sent to a dead machine. What has to be
 * cleared is the *parent's* reference to a child that no longer exists, and only
 * when it is still ours: a sibling may have taken the slot.
 */
function useMenuTree(
  api: MenuApi,
  service: Service<menu.MenuSchema>,
  parent: MenuContextValue | null,
): void {
  const parentService = parent?.service ?? null;

  // The two services and nothing else. Keying this on the apis would re-run it on
  // every render, and re-running it is not free: the effect would hand the slot
  // back to itself after a sibling had rightfully claimed it (`claimChild` below).
  useSafeLayoutEffect(() => {
    if (parent === null || parentService === null) return;
    api.setParent(parentService);
    parent.api.setChild(service);
    return () => {
      // React unmounts a deletion from the top down, so the parent is usually gone
      // before this runs — and an event sent to a stopped service is a dev warning
      // about nothing. What matters is the case where the parent outlives us.
      if (parentService.status() !== "started") return;
      if (parentService.refs.get("child") === service) parent.api.setChild(null);
    };
  }, [service, parentService]);
}

/**
 * Hand this submenu its parent's one child slot.
 *
 * The machine holds a single child, so a menu with two submenus has to pass the
 * slot along as the highlight moves — otherwise hovering the first trigger item
 * opens the second submenu, anchored to a node the pointer is nowhere near.
 * Handing it over also has to close whatever was in it: once the slot is gone
 * nothing holds that service any more, and it would stay open with no way back.
 *
 * Driven by the parent's own highlight rather than by the pointer, which is what
 * keeps the safe triangle intact: a pointer cutting across this item towards an
 * already-open sibling never moves the highlight, so it never takes the slot.
 *
 * `CHILD.CLOSE` is sent only while a child is actually open — with none, the
 * parent reads the very same event as `back` and closes *itself*.
 */
function claimChild(parent: MenuContextValue, child: Service<menu.MenuSchema>): void {
  const current = parent.service.refs.get("child");
  if (current === child) return;
  if (current?.context.get("open") === true) parent.service.send({ type: "CHILD.CLOSE" });
  parent.api.setChild(child);
}

export interface MenuRootProps extends UseMenuProps {
  readonly keepMounted?: boolean | undefined;
  readonly children?: ReactNode;
}

export function MenuRoot(props: MenuRootProps): ReactNode {
  const { children, keepMounted, ...machineProps } = props;
  const parent = MenuContext.useOptional();
  const service = useMenuService(machineProps, parent);
  const api = menu.connect(service, normalizeProps);
  const { motion } = useEnvironment();
  // See the note in `dialog.tsx`: `reduced` keeps the fade, only `none` removes it.
  const immediate = motion === "none";

  // Two presences: the scrim and the surface run different exits, and one presence
  // can only measure the animations of the node it holds.
  const backdrop = usePresence({ present: api.open, immediate });
  const content = usePresence({ present: api.open, immediate });

  useMenuTree(api, service, parent);

  const value: MenuContextValue = {
    api,
    service,
    parent,
    keepMounted: keepMounted === true,
    backdrop,
    content,
  };

  return (
    <LayerProvider layerId={menu.getContentId(service.scope)}>
      <MenuContext.Provider value={value}>{children}</MenuContext.Provider>
    </LayerProvider>
  );
}

/**
 * Read straight off the machine in the open direction, never off the presence: the
 * interpreter installs the open state's effects in the layout effect of the very
 * commit that opened it, and every one of them looks the surface up by id. The
 * presence only ever extends the mount past the close.
 */
function isMounted(context: MenuContextValue, presence: PresenceApi): boolean {
  return context.keepMounted || context.api.open || presence.present;
}

function usePresenceRef(
  presence: PresenceApi,
  consumer: Ref<HTMLElement> | undefined,
): Ref<HTMLElement> {
  return useMemo(() => composeRefs(presence.ref, consumer), [presence.ref, consumer]);
}

export const MenuTrigger: (props: PartProps<"button">) => ReactNode = createPart(MenuContext, {
  name: "MenuTrigger",
  element: "button",
  props: (context) => context.api.getTriggerProps(),
});

/**
 * Any container, and it carries no handler of its own: the `contextmenu` listener
 * and the long press are installed natively by the machine, because they have to
 * be listening while the surface is closed.
 */
export const MenuContextTrigger: (props: PartProps<"div">) => ReactNode = createPart(MenuContext, {
  name: "MenuContextTrigger",
  element: "div",
  props: (context) => context.api.getContextTriggerProps(),
});

/** The chevron on the trigger. Decoration — `aria-hidden`, no name of its own. */
export const MenuIndicator: (props: PartProps<"span">) => ReactNode = createPart(MenuContext, {
  name: "MenuIndicator",
  element: "span",
  props: (context) => context.api.getIndicatorProps(),
});

export interface MenuPortalProps extends Omit<PortalProps, "children"> {
  readonly children?: ReactNode;
}

export function MenuPortal(props: MenuPortalProps): ReactNode {
  const { children, disabled, ...portalProps } = props;
  const context = MenuContext.usePart("MenuPortal");
  const present = isMounted(context, context.backdrop) || isMounted(context, context.content);

  // A submenu in the `sheet` presentation is drilled in, not cascaded: its surface
  // is stacked inside its parent's. That is also what lets the machine tell the two
  // item lists apart — `getItemEls` stops at the nearest `content` — so portalling
  // it would hand the parent's roving list a second menu's items.
  const drillIn = context.parent !== null && context.api.presentation === "sheet";

  if (!present) return null;
  return (
    <Portal {...portalProps} disabled={disabled ?? drillIn}>
      {children}
    </Portal>
  );
}

/**
 * The scrim, and the sheet's alone (spec §3). An anchored menu that dimmed the page
 * would swallow the very click that is meant to dismiss it, and a scrim left in the
 * tree for CSS to hide is still a full-page surface catching pointers.
 */
export function MenuBackdrop(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = MenuContext.usePart("MenuBackdrop");
  const composed = usePresenceRef(context.backdrop, ref);

  // Rendered then discarded rather than returned early: `useRender` is a hook, and
  // a density flip must not change how many of them this component runs.
  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getBackdropProps(),
    elementProps: { ...elementProps, ref: composed },
    children,
  });

  if (context.api.presentation !== "sheet") return null;
  return isMounted(context, context.backdrop) ? element : null;
}

export function MenuPositioner(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = MenuContext.usePart("MenuPositioner");

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getPositionerProps(),
    elementProps,
    children,
  });

  return isMounted(context, context.content) ? element : null;
}

export interface MenuContentProps extends PartProps<"div"> {
  /**
   * The action sheet's Cancel button, rendered for you (components.md §3-1): pass
   * the word and the part appears in the `sheet` presentation and nowhere else.
   * Left out, nothing is added — the library ships no copy of its own, and a
   * nameless button is worse than none (the machine warns about one in dev).
   */
  readonly cancelLabel?: ReactNode;
}

/**
 * The scroll affordance, and the reason it is two nodes the adapter writes rather
 * than a part or a pseudo-element.
 *
 * Not a part: nothing composes into it, nothing is rendered inside it, and the
 * anatomy is the list of what a consumer can reach. It is decoration the surface
 * owes itself, like the submenu chevron and the glass rim — both of which are
 * pseudo-elements, and both of which are why these cannot be: `::before` is the
 * rim already, and one `::after` cannot be at two edges at once.
 *
 * They must be the **outermost** children on both sides: the top band is what the
 * first row slides under, and the bottom band has to cover the sheet's Cancel row,
 * which is still inside the scroller.
 */
const SCROLL_EDGES = {
  up: <div data-scroll-edge="up" aria-hidden="true" />,
  down: <div data-scroll-edge="down" aria-hidden="true" />,
};

export function MenuContent(props: MenuContentProps): ReactNode {
  const { render, asChild, children, cancelLabel, ref, ...elementProps } = props;
  const context = MenuContext.usePart("MenuContent");
  const composed = usePresenceRef(context.content, ref);

  const element = useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getContentProps(),
    elementProps: { ...elementProps, ref: composed },
    children: (
      <>
        {SCROLL_EDGES.up}
        {children}
        {cancelLabel === undefined ? null : <MenuCancelTrigger>{cancelLabel}</MenuCancelTrigger>}
        {SCROLL_EDGES.down}
      </>
    ),
  });

  return isMounted(context, context.content) ? element : null;
}

export interface MenuItemGroupProps extends PartProps<"div", menu.MenuItemGroupProps> {
  /** Any stable key of the consumer's; a `useId()` when they have none. */
  readonly id?: string | undefined;
  /**
   * **A flag, not the text.** Say `label` when the group renders a
   * `MenuItemGroupLabel`, and `aria-labelledby` is wired to it. Left out, the
   * group carries no reference at all — which is deliberate: written blind, the
   * attribute points at an element nobody rendered, and a group with a dead IDREF
   * has no accessible name *and* nothing to report it, since axe grades that
   * `incomplete` rather than a violation. Same shape as `description` on an item.
   */
  readonly label?: boolean | undefined;
  /** `horizontal` is reserved for the iOS Control Group, out of scope for v1. */
  readonly orientation?: "vertical" | "horizontal" | undefined;
}

export function MenuItemGroup(props: MenuItemGroupProps): ReactNode {
  const [group, rest] = splitProps(props, ["id", "label", "orientation"]);
  const { render, asChild, children, ...elementProps } = rest;
  const context = MenuContext.usePart("MenuItemGroup");
  const fallback = useId();
  // Published so the label does not have to repeat it — the two ids are derived
  // from the same key, which is the whole of `aria-labelledby` here.
  const key = group.id ?? fallback;

  return (
    <MenuGroupContext.Provider value={key}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: context.api.getItemGroupProps({
          id: key,
          label: group.label,
          orientation: group.orientation,
        }),
        elementProps,
        children,
      })}
    </MenuGroupContext.Provider>
  );
}

export function MenuItemGroupLabel(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = MenuContext.usePart("MenuItemGroupLabel");
  const htmlFor = MenuGroupContext.usePart("MenuItemGroupLabel");

  return useRender({
    render,
    asChild,
    element: "div",
    props: context.api.getItemGroupLabelProps({ htmlFor }),
    elementProps,
    children,
  });
}

const ITEM_KEYS = [
  "value",
  "disabled",
  "destructive",
  "label",
  "closeOnSelect",
  "shortcut",
  "description",
] as const;

const OPTION_KEYS = [...ITEM_KEYS, "type", "checked", "onCheckedChange"] as const;

export interface MenuItemProps extends menu.MenuItemProps, PartProps<"div", menu.MenuItemProps> {}

export function MenuItem(props: MenuItemProps): ReactNode {
  const [item, rest] = splitProps(props, ITEM_KEYS);
  const { render, asChild, children, ...elementProps } = rest;
  const context = MenuContext.usePart("MenuItem");

  return (
    <MenuItemContext.Provider value={{ value: item.value, checked: undefined }}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: context.api.getItemProps(item),
        elementProps,
        children,
      })}
    </MenuItemContext.Provider>
  );
}

export interface MenuOptionItemProps
  extends menu.MenuOptionItemProps,
    PartProps<"div", menu.MenuOptionItemProps> {}

/**
 * Checkable and radio items, and the checked state stays the consumer's — the menu
 * reports the flip and never stores it. A transient surface is the wrong place for
 * a value the app already owns.
 */
export function MenuOptionItem(props: MenuOptionItemProps): ReactNode {
  const [item, rest] = splitProps(props, OPTION_KEYS);
  const { render, asChild, children, ...elementProps } = rest;
  const context = MenuContext.usePart("MenuOptionItem");

  return (
    <MenuItemContext.Provider value={{ value: item.value, checked: item.checked }}>
      {useRender({
        render,
        asChild,
        element: "div",
        props: context.api.getOptionItemProps(item),
        elementProps,
        children,
      })}
    </MenuItemContext.Provider>
  );
}

export interface MenuTriggerItemProps
  extends menu.MenuItemProps,
    PartProps<"div", menu.MenuItemProps> {}

/**
 * The item that opens a submenu — written **inside** the nested `<MenuRoot>`, which
 * is what puts both apis within reach: the parent's item props and this menu's own
 * trigger props land on one node, under one part token.
 */
export function MenuTriggerItem(props: MenuTriggerItemProps): ReactNode {
  const [item, rest] = splitProps(props, ITEM_KEYS);
  const { render, asChild, children, ...elementProps } = rest;
  const context = MenuContext.usePart("MenuTriggerItem");
  const { parent, service } = context;
  const parentService = parent?.service ?? null;
  const isCurrent = parent !== null && parent.api.highlightedValue === item.value;

  useSafeLayoutEffect(() => {
    if (parent === null || !isCurrent) return;
    claimChild(parent, service);
  }, [parentService, isCurrent, service]);

  invariant(parent !== null, "<MenuTriggerItem> must be rendered inside a nested <MenuRoot>");

  return useRender({
    render,
    asChild,
    element: "div",
    props: parent.api.getTriggerItemProps(context.api, item),
    // The claim again, ahead of the machine's own click: a tap never produces the
    // `pointermove` that moves the highlight, so touch would otherwise open
    // whichever sibling happened to mount last.
    elementProps: mergeProps(
      { onClick: () => claimChild(parent, service) },
      elementProps as AnyProps,
    ),
    children,
  });
}

/**
 * The reserved symbol column — a reserved symbol space. Give it an
 * inline SVG, never a text glyph: text stands on its font's baseline inside the
 * centred line box, so its ink paints below the box's centre while an SVG's
 * viewBox fills the square.
 */
export const MenuItemSymbol: (props: PartProps<"span">) => ReactNode = createPart(MenuContext, {
  name: "MenuItemSymbol",
  element: "span",
  props: (context) => context.api.getItemSymbolProps(),
});

/** The item's accessible name. */
export const MenuItemText: (props: PartProps<"span">) => ReactNode = createPart(MenuContext, {
  name: "MenuItemText",
  element: "span",
  props: (context) => context.api.getItemTextProps(),
});

/** Decoration: the shortcut reaches assistive tech as `aria-keyshortcuts`. */
export const MenuItemShortcut: (props: PartProps<"kbd">) => ReactNode = createPart(MenuContext, {
  name: "MenuItemShortcut",
  element: "kbd",
  props: (context) => context.api.getItemShortcutProps(),
});

export const MenuSeparator: (props: PartProps<"div">) => ReactNode = createPart(MenuContext, {
  name: "MenuSeparator",
  element: "div",
  props: (context) => context.api.getSeparatorProps(),
});

function createItemPart(
  name: string,
  getter: (api: MenuApi, item: MenuItemContextValue) => object,
): (props: PartProps<"span">) => ReactNode {
  return function ItemPart(props: PartProps<"span">): ReactNode {
    const { render, asChild, children, ...elementProps } = props;
    const context = MenuContext.usePart(name);
    const item = MenuItemContext.usePart(name);

    return useRender({
      render,
      asChild,
      element: "span",
      props: getter(context.api, item),
      elementProps,
      children,
    });
  };
}

/** The iOS subtitle; referenced by the item's `aria-describedby`. */
export const MenuItemDescription: (props: PartProps<"span">) => ReactNode = createItemPart(
  "MenuItemDescription",
  (api, item) => api.getItemDescriptionProps({ value: item.value }),
);

/**
 * The checkmark. The state is `aria-checked` on the item, never this glyph — and
 * like the symbol it takes an inline SVG, not a `✓` character, whose baseline
 * would sink the ink below the centre the symbols share.
 */
export const MenuItemIndicator: (props: PartProps<"span">) => ReactNode = createItemPart(
  "MenuItemIndicator",
  (api, item) => api.getItemIndicatorProps({ checked: item.checked }),
);

/**
 * The sheet's Cancel row, and only the sheet's: a desktop menu has none, and one
 * left in the tree for CSS to hide would still be a focusable control in the tab
 * order of a surface that never shows it.
 */
export function MenuCancelTrigger(props: PartProps<"button">): ReactNode {
  const { render, asChild, children, ...elementProps } = props;
  const context = MenuContext.usePart("MenuCancelTrigger");

  const element = useRender({
    render,
    asChild,
    element: "button",
    props: context.api.getCancelTriggerProps(),
    elementProps,
    children,
  });

  return context.api.presentation === "sheet" ? element : null;
}
